export const GOLDENDICT_VENDOR_CSS: Readonly<Record<GoldenDictVendorStylesheet, string>> = {"article-style.css":"/******** Global, non-dictionary-specific classes ***********/\n\nhtml {\n  height: 100%;\n  scrollbar-gutter: stable;\n}\n\nbody {\n  --text-color: #222;\n  --secondary-text-color: #555;\n  --link-color: #005a9c;\n  --container-bg: #f9f9f9;\n  --border-color: #e3e3e3;\n  --accent-color: #c00;\n  --selection-bg: #c00;\n  --selection-text: #fff;\n  font-family:\n    -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Oxygen-Sans, Ubuntu,\n    Cantarell, \"Helvetica Neue\", Arial, \"Apple Color Emoji\", \"Segoe UI Emoji\",\n    \"Segoe UI Symbol\", sans-serif;\n}\n\n.ipa,\n.phon,\n.phone,\n.pron,\n.audio-gb,\n.audio-us {\n  font-family:\n    \"Segoe UI\", \"Lucida Grande\", \"Lucida Sans\", \"Droid Sans Mono\", \"Droid Sans\",\n    \"Arial Unicode MS\", \"Charis SIL\", \"Open Sans\", Roboto, Helvetica, Arial,\n    normal;\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  unicode-bidi: plaintext;\n}\n\np,\nem,\narticle,\nheader,\nsection,\nmain,\nspan,\ndiv,\ngd-section-html,\ngd-section-body,\ngd-section-head {\n  unicode-bidi: plaintext;\n}\n\ngd-section-html,\ngd-section-body {\n  display: block;\n}\n\ngd-section-head {\n  display: none;\n}\n/* This stylesheet is used to highligh current selection when doing a search.\n  It changes the default selection color (e.g. blue under Windows, orange under Ubuntu) */\n\n/* highlight/select color in Windows when a widget is inactive is nearly impossible to read (light gray).\n * then change it to green to use with the find option. */\n::selection {\n  background: var(--selection-bg);\n  color: var(--selection-text);\n}\n\n/* Don't allow to select [] */\n:before,\n:after {\n  user-select: none;\n}\n\n/* Plaintext dictionaries are usually 80-column formatted and take a lot\n * of space. We try to use smaller fonts for them therefore. */\npre {\n  font-size: 0.75rem;\n}\n\n/* Dictionary's name heading */\ngd-dict-header,\n.gddictname {\n  display: flow-root;\n  margin-top: 0.5em;\n  margin-bottom: 0.5em;\n  font-weight: bold;\n  font-size: 0.8em;\n  padding: 0.3em;\n  padding-left: 0.5em;\n  background: #def;\n  user-select: none;\n}\n/* The Anki plus button, which is shown if enabled. */\n.ankibutton {\n  float: none;\n  display: flex;\n  margin-left: auto;\n  margin-right: 0;\n  margin-top: 10px;\n  margin-bottom: 8px;\n  width: 32px;\n  height: 32px;\n  padding: 0;\n  border-radius: 4px;\n  cursor: pointer;\n  text-decoration: none;\n  transition:\n    background-color 0.2s,\n    transform 0.2s;\n}\n\n.ankibutton:hover {\n  transform: scale(1.1);\n}\n\n.ankibutton:active {\n  background-color: hsl(0deg 0% 70%);\n  transform: scale(0.95);\n}\n\n.ankibutton:focus {\n  outline: 2px solid var(--link-color);\n  outline-offset: 2px;\n}\n\n.ankibutton img {\n  display: block;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n}\n.gddicttitle {\n  user-select: none;\n}\n\n.gdarticlebody {\n  clear: both;\n}\n\n/* The 'From ' string which precedes dictionary name in the heading */\n.gdfromprefix {\n  display: none;\n}\n\n/* The article span. Here we have a padding/margin hack to make fragment links\n   behave better (have some space before the start of article) */\n.gdarticle {\n  display: flow-root;\n  padding-top: 1px;\n  margin-top: -8px;\n  margin-bottom: 8px;\n  /*fix for invalid blg*/\n  font-style: normal;\n}\n\n.empty-space {\n  height: 400px;\n}\n\n/* CSS trick to prevent the floating elements to overflow\n   the article boundaries, see Issue #333. */\n.gdarticle:after {\n  content: \"\";\n  display: block;\n  height: 0;\n  clear: both;\n}\n\n/* Appears between the articles */\n.gdarticleseparator {\n  display: inline-block;\n  clear: both;\n}\n\n/* Dictionary query error description string */\n.gderrordesc {\n  font-style: italic;\n  background: url(\"qrc:///icons/warning.svg\") center left no-repeat !important;\n  background-size: auto min(100%, 24px);\n  padding-left: 2em !important;\n  margin: 1em;\n}\n\n/********* Babylon dictionaries' classes *********/\n\n/* Transcriptions in Babylon dictionaries */\n.bgltrn:before {\n  content: \"[\";\n}\n\n.bgltrn:after {\n  content: \"]\";\n}\n\n.bgltrn {\n  display: block;\n}\n\n/* Part of speech in Babylon dictionaries. Usually irrelevant,\n * therefore hidden */\n.bglpos {\n  display: none;\n}\n\n/* Right-to-left text */\n.bglrtl {\n  text-align: right;\n  direction: rtl;\n}\n\n/******** StarDict dictionaries' classes *********/\n\n/* StarDict type 'h' -- Html content. We don't normally do anything here. */\ndiv.sdct_h {\n  unicode-bidi: plaintext;\n}\n\n.sdict_h_wav img {\n  vertical-align: middle;\n}\n\n/* StarDict type 'm' -- Pure meaning. Presented as <pre> */\n.sdct_m {\n}\n\n/* StarDict type 'l' -- Pure meaning which used to be in locale encoding. */\n.sdct_l {\n}\n\n/* StarDict type 'g' -- Pango Markup */\n.sdct_g {\n}\n\n/* StarDict type 't' -- Transcription */\n.sdct_t {\n  font-weight: bold;\n}\n\n/* StarDict type 'y' -- Chinese YinBiao or Japanese KANA */\n.sdct_y {\n}\n\n/* StarDict type 'x'. Should have xdxf_*-styled elements inside */\n.sdct_x {\n}\n\n/* Blockquotes in XDXF-styled elements are used\n   for indentation purposes, see Issue #305. */\n.sdct_x blockquote {\n  margin: 0px;\n  padding-left: 9px;\n  display: inline-block;\n}\n\n/******** XDXF markup classes *********/\n\ndiv.xdxf {\n}\n\n/* Key -- keys shouldn't normally be present in the article's body since they\n * are accounted for separately, hence we hide them */\n.xdxf_k {\n  display: none;\n}\n\n/* ...and if there's a break after it, we hide it too so we don't have an\n * extra vertical spacing. */\n.xdxf_k + br {\n  display: none;\n}\n\n/* Article structure tag */\n.xdxf_num {\n  color: red;\n  font-weight: bold;\n  padding-left: -15px;\n}\n.xdxf_def {\n  display: block;\n  border-color: #e3e3e3;\n  border-width: 1px;\n  border-style: dashed;\n  margin: 1px;\n  margin-left: 15px;\n}\n\n.xdxf_def:target {\n  /* this pseudoclass is used to marked out the referenced <def> that was just clicked */\n  border-color: red;\n  border-width: 1px;\n  border-style: double;\n}\n\n/* Abbreviation */\n.xdxf_abbr {\n  font-style: italic;\n  color: seagreen;\n  cursor: default;\n  border-bottom: 1px seagreen dotted;\n}\n\n/* Editorial comment */\n.xdxf_co,\n.xdxf_co_old {\n  color: darkslateblue;\n  font-style: italic;\n}\n.xdxf_co:before {\n  content: \"(\";\n}\n.xdxf_co:after {\n  content: \")\";\n}\n\n/* Grammar information */\n.xdxf_gr {\n  color: orangered;\n  display: block;\n}\n\n.xdxf_gr_old {\n  color: blue; /*orangered;*/\n}\n\n/* Example */\n.xdxf_ex {\n  color: #808080;\n  display: block;\n  margin-left: 14px;\n}\n\n.xdxf_ex_old {\n  color: #808080;\n}\n\n.xdxf_ex_source:before {\n  content: \"[\";\n}\n.xdxf_ex_source:after {\n  content: \"]\";\n}\n\n.xdxf_ex_orig {\n  color: #8761d9;\n}\n\n.xdxf_ex_tran:before {\n  content: \"— \";\n}\n\n.xdxf_ex_tran {\n  font-style: italic;\n}\n\n/* Direct translation */\n.xdxf_dtrn {\n  font-weight: bold;\n  color: #dd7800;\n}\n\n/* Transcription */\n.xdxf_tr:before {\n  content: \"[\";\n}\n\n.xdxf_tr:after {\n  content: \"]\";\n}\n\n.xdxf_tr,\n.xdxf_tr_old {\n  font-weight: bold;\n}\n\n/* Resource reference -- for now just a span. Since there's not yet a mechanism\n * to load resources off XDXF articles in GoldenDict, we just hide them. */\n.xdxf_rref {\n  display: none;\n}\n\n.xdxf_headwords {\n  font-size: 116%;\n  font-weight: bold;\n  margin-top: 10px;\n  margin-bottom: 10px;\n}\n\n/* The words in examples that are meaked out; they are marked out only when placed into <ex> tag */\n.xdxf_ex .xdxf_ex_markd,\n.xdxf_ex_old .xdxf_ex_markd {\n  background-color: lightgray;\n  margin-left: 0.2em;\n  margin-right: 0.2em;\n  padding-left: 0.1em;\n  padding-right: 0.1em;\n}\n\n.xdxf_opt {\n  color: #808080;\n}\n\n/******** SDictionary markup classes *********/\n\n.sdict_forms {\n  font-style: italic;\n}\n\n/* Transcription */\n.sdict_tr:before {\n  content: \"[\";\n}\n\n.sdict_tr:after {\n  content: \"] \";\n}\n\n.sdict_tr {\n  font-weight: bold;\n}\n\n/************* audio archives **************/\n\n.audio-play {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 10px;\n}\n.audio-play-item {\n  display: flex;\n  align-items: center;\n}\n.audio-play-item a {\n  text-decoration: none;\n  color: inherit;\n  margin-right: 10px;\n}\n.audio-play-item img {\n  border: 0;\n  vertical-align: middle;\n  width: 24px;\n  height: 24px;\n}\n\n.audio-play-icon {\n  display: inline-block;\n  width: 24px; /* Adjust the width as needed */\n  height: 24px; /* Adjust the height as needed */\n  background-image: url(\"qrc:///icons/playsound.svg\");\n  background-size: cover;\n  background-repeat: no-repeat;\n}\n\n/************* DSL dictionaries **************/\n\n.dsl_u {\n  text-decoration: underline;\n}\n\n.dsl_article {\n  display: inline;\n}\n\n.dsl_article .c_default_color {\n  color: green;\n}\n\n.dsl_m,\n.dsl_m0 {\n  padding-left: 0px;\n}\n\n.dsl_m1 {\n  padding-left: 9px;\n}\n\n.dsl_m2 {\n  padding-left: 18px;\n}\n\n.dsl_m3 {\n  padding-left: 27px;\n}\n\n.dsl_m4 {\n  padding-left: 36px;\n}\n\n.dsl_m5 {\n  padding-left: 45px;\n}\n\n.dsl_m6 {\n  padding-left: 54px;\n}\n\n.dsl_m7 {\n  padding-left: 63px;\n}\n\n.dsl_m8 {\n  padding-left: 72px;\n}\n\n.dsl_m9 {\n  padding-left: 81px;\n}\n\n.dsl_p, .dsl_p :not(a) /* DSL Feature: Enforce the style even if the children tags say otherwise, except links */ {\n  color: green !important; /* DSL label color must have highest priority */\n  font-style: italic;\n  cursor: default;\n  font-weight: normal; /* DSL feature: labels are always of normal weight */\n}\n\n.dsl_stress_without_accent {\n  display: none;\n}\n\n.dsl_t {\n  font-weight: bold;\n}\n\n.dsl_headwords {\n  font-weight: bold;\n  margin-top: 15px;\n  margin-bottom: 10px;\n}\n\n.dsl_headwords p {\n  font-weight: bold;\n  font-size: 15px;\n  margin: 0;\n}\n\n.dsl_definition p {\n  margin: 0;\n}\n\n.dsl_opt {\n  display: none;\n}\n\n.dsl_opt,\n.dsl_opt .dsl_ex,\n.dsl_opt .dsl_ex :not(a),\n.dsl_opt .dsl_ex [color] /* DSL Feature: Enforce the optional zone color even if the children tags say otherwise */ {\n  color: gray;\n}\n\n.dsl_ex,\n.dsl_ex .dsl_opt {\n  color: gray;\n}\n\n.dsl_unknown {\n  border-bottom: 3px double red;\n}\n\n/* Style for expand optional parts button */\n.hidden_expand_opt {\n  color: blue;\n  cursor: pointer;\n  vertical-align: text-bottom;\n  width: 16px;\n  height: auto;\n}\n\n.dsl_s_wav img {\n  vertical-align: middle;\n}\n\n.dsl_video .img {\n  display: inline-block;\n  background: url(\"qrc:///icons/video.svg\");\n  background-repeat: no-repeat;\n  vertical-align: middle;\n  width: 22px;\n  height: 22px;\n  margin: 0;\n  padding: 0;\n}\n\n.dsl_video .filename {\n  display: none; /* by default, the file name is hidden */\n  padding-left: 5px;\n}\n\n/************* MDict dictionaries **************/\n.mdict {\n}\n\n.mdict a[name] {\n  text-decoration: none;\n  color: inherit;\n}\n\n/************* Zim dictionaries **************/\n\n.zimdict {\n  font-size: 110% !important;\n}\n\n.zimdict_headword {\n  font-weight: bold !important;\n  display: none;\n}\n\n/************* Spelling suggestions *****************/\n\n.gdspellsuggestion {\n  /* Add some vertical space before the article */\n  margin-top: 1em;\n}\n\n/************* Stemmed suggestions *****************/\n\n.gdstemmedsuggestion {\n  /* Add some horizontal and vertical space */\n  margin-top: 1em;\n  margin-left: 1px;\n}\n\n.gdstemmedsuggestion_head {\n  margin-left: 12px;\n  font-style: italic;\n}\n\n.gdstemmedsuggestion_body {\n  display: block;\n  width: 100%;\n  margin: 12px;\n\n  box-sizing: border-box;\n  overflow-wrap: break-word;\n  line-height: 1.5;\n}\n\n/************* Dictd articles *****************/\n.dictd_article {\n  /* Add some vertical space before the article */\n  margin-top: 1em;\n}\n\n.dictd_phonetic:before,\n.dictd_phonetic:after {\n  content: \"\\\\\";\n  font-style: normal;\n}\n\n.dictd_phonetic:after {\n  margin-left: 3px;\n}\n\n.dictd_phonetic {\n  font-style: italic;\n  color: #009900;\n}\n\n.dictd_article a:link {\n  color: #0000ff;\n}\n\n.dictserver_from {\n  font-size: 110%;\n  font-weight: 600;\n}\n\n/************* Epwing dictionaries *****************/\n\n.epwing_narrow_font {\n  width: 0.5em;\n  height: 1em;\n  vertical-align: -15%;\n}\n\n.epwing_wide_font {\n  width: 1em;\n  height: 1em;\n  vertical-align: -15%;\n}\n\n.epwing_article {\n  display: inline;\n}\n\n.epwing_article h3 {\n  color: #0f2fa0;\n}\n\n.epwing_text b {\n  color: #0089a2;\n}\n\n.epwing_text i {\n  color: #ae4500;\n}\n\n.epwing_text a {\n  text-decoration: none;\n  cursor: pointer;\n  color: #859aad;\n}\n\n.epwing_text {\n  line-height: 1.5em;\n}\n/************* Websites *****************/\n\n.website_padding {\n  height: 1em;\n  clear: both;\n}\n\n.website-iframe {\n  overflow: auto;\n  width: 100%;\n  display: block;\n  border: none;\n  max-height: 800px;\n  min-height: 550px;\n}\n/************* Forvo **************/\n\n.forvo_headword {\n  margin-top: 15px;\n  margin-bottom: 10px;\n  font-weight: bold;\n  font-size: 15px;\n}\n\n/* A table which contains a play icon and information about the sound */\n.forvo_play {\n  margin-top: 8px;\n  margin-left: 8px;\n}\n\n.forvo_user {\n  text-decoration: none;\n  color: green;\n}\n\n.forvo_location {\n  color: grey;\n}\n\n.forvo_positive_votes {\n  font-weight: bold;\n  color: green;\n}\n\n.forvo_negative_votes {\n  font-weight: bold;\n  color: red;\n}\n\n/************* MediaWiki articles *****************\n The following consist of excerpts from different .css files edited\n with a .mwiki prepended to each record.\n*/\n\n.mwiki {\n  /* Add some vertical space before the article */\n  margin-top: 1em;\n}\n\n.mwiki .topicon {\n  /* Those are padlocks on top and such -- we disable those for GoldenDict\n     since they look really ugly here */\n  display: none;\n}\n\n/* Hide empty list items */\n.mwiki .mw-empty-li,\n.mwiki .mw-empty-elt {\n  display: none;\n}\n\n/************ common.css **************/\n\n/**\n * CSS in this file is used by *all* skins (that have any CSS at all).  Be\n * careful what you put in here, since what looks good in one skin may not in\n * another, but don't ignore the poor non-Monobook users either.\n */\n.mwiki .mw-plusminus-null {\n  color: #aaa;\n}\n\n.mwiki .texvc {\n  direction: ltr;\n  unicode-bidi: embed;\n}\n.mwiki img.tex {\n  vertical-align: middle;\n}\n.mwiki span.texhtml {\n  font-family: serif;\n}\n\n/* add a bit of margin space between the preview and the toolbar */\n/* this replaces the ugly <p><br /></p> we used to insert into the page source */\n.mwiki #wikiPreview.ontop {\n  margin-bottom: 1em;\n}\n\n/* Stop floats from intruding into edit area in previews */\n.mwiki #toolbar,\n.mwiki #wpTextbox1 {\n  clear: both;\n}\n\n.mwiki div#mw-js-message {\n  margin: 1em 5%;\n  padding: 0.5em 2.5%;\n  border: solid 1px #ddd;\n  background-color: #fcfcfc;\n}\n\n/* Edit section links */\n.mwiki .editsection {\n  float: right;\n  margin-left: 5px;\n}\n\n/**\n * File histories\n */\n.mwiki table.filehistory {\n  border: 1px solid #ccc;\n  border-collapse: collapse;\n}\n\n.mwiki table.filehistory th,\n.mwiki table.filehistory td {\n  padding: 0 0.2em 0 0.2em;\n  vertical-align: top;\n  border: 1px solid #ccc;\n}\n.mwiki table.filehistory th {\n  text-align: left;\n}\n.mwiki table.filehistory td.mw-imagepage-filesize,\n.mwiki table.filehistory th.mw-imagepage-filesize {\n  white-space: nowrap;\n}\n\n.mwiki table.filehistory td.filehistory-selected {\n  font-weight: bold;\n}\n\n/*\n * rev_deleted stuff\n */\n.mwiki li span.deleted,\n.mwiki span.history-deleted {\n  text-decoration: line-through;\n  color: #888;\n  font-style: italic;\n}\n\n.mwiki td.mw-label {\n  vertical-align: top;\n}\n.mwiki td.mw-submit {\n  white-space: nowrap;\n}\n/**\n * Forms\n */\n.mwiki body.ltr td.mw-label {\n  text-align: right;\n}\n.mwiki body.ltr td.mw-input {\n  text-align: left;\n}\n.mwiki body.ltr td.mw-submit {\n  text-align: left;\n}\n.mwiki body.rtl td.mw-label {\n  text-align: left;\n}\n.mwiki body.rtl td.mw-input {\n  text-align: right;\n}\n.mwiki body.rtl td.mw-submit {\n  text-align: right;\n}\n\n/**\n * Image captions\n */\n.mwiki body.rtl .thumbcaption {\n  text-align: right;\n}\n.mwiki body.rtl .magnify {\n  float: left;\n}\n\n.mwiki body.ltr .thumbcaption {\n  text-align: left;\n}\n.mwiki body.ltr .magnify {\n  float: right;\n}\n\n/**\n * Hidden categories\n */\n.mwiki .mw-hidden-cats-hidden {\n  display: none;\n}\n.mwiki .catlinks-allhidden {\n  display: none;\n}\n\n/* Convenience links to edit block, delete and protect reasons */\n.mwiki p.mw-ipb-conveniencelinks,\n.mwiki p.mw-protect-editreasons,\n.mwiki p.mw-filedelete-editreasons,\n.mwiki p.mw-delete-editreasons {\n  font-size: 90%;\n  float: right;\n}\n\n/* Search results */\n.mwiki div.searchresult {\n  font-size: 95%;\n  width: 38em;\n}\n.mwiki .mw-search-results li {\n  padding-bottom: 1em;\n  list-style: none;\n}\n.mwiki .mw-search-result-data {\n  color: green;\n  font-size: 97%;\n}\n\n.mwiki td#mw-search-menu {\n  padding-left: 6em;\n  font-size: 85%;\n}\n\n.mwiki div#mw-search-interwiki {\n  float: right;\n  width: 18em;\n  border-style: solid;\n  border-color: #aaaaaa;\n  border-width: 1px;\n  margin-top: 2ex;\n}\n\n.mwiki div#mw-search-interwiki li {\n  font-size: 95%;\n}\n\n.mwiki .mw-search-interwiki-more {\n  float: right;\n  font-size: 90%;\n}\n\n.mwiki span.searchalttitle {\n  font-size: 95%;\n}\n\n.mwiki div.searchdidyoumean {\n  font-size: 127%;\n  margin-bottom: 1ex;\n  margin-top: 1ex;\n  /* Note that this color won't affect the link, as desired. */\n  color: #c00;\n}\n\n.mwiki div.searchdidyoumean em {\n  font-weight: bold;\n}\n\n.mwiki .searchmatch {\n  font-weight: bold;\n}\n\n.mwiki div.searchresults {\n  border: 1px solid darkblue;\n  padding-top: 10px;\n  padding-bottom: 10px;\n  padding-left: 20px;\n  padding-right: 20px;\n}\n\n/*\n * UserRights stuff\n */\n.mwiki .mw-userrights-disabled {\n  color: #888;\n}\n\n.mwiki table.mw-userrights-groups * td,\n.mwiki table.mw-userrights-groups * th {\n  padding-right: 1.5em;\n}\n\n/*\n * OpenSearch ajax suggestions\n */\n.mwiki .os-suggest {\n  overflow: auto;\n  overflow-x: hidden;\n  position: absolute;\n  top: 0px;\n  left: 0px;\n  width: 0px;\n  background-color: white;\n  border-style: solid;\n  border-color: #aaaaaa;\n  border-width: 1px;\n  z-index: 99;\n  visibility: hidden;\n  font-size: 95%;\n}\n\n.mwiki table.os-suggest-results {\n  font-size: 95%;\n  cursor: pointer;\n  border: 0;\n  border-collapse: collapse;\n  width: 100%;\n}\n\n.mwiki td.os-suggest-result,\n.mwiki td.os-suggest-result-hl {\n  white-space: nowrap;\n  background-color: white;\n  color: black;\n  padding: 2px;\n}\n.mwiki td.os-suggest-result-hl,\n.mwiki td.os-suggest-result-hl-webkit {\n  background-color: #4c59a6;\n  color: white;\n}\n\n.mwiki .os-suggest-toggle {\n  position: relative;\n  left: 1ex;\n  font-size: 65%;\n}\n.mwiki .os-suggest-toggle-def {\n  position: absolute;\n  top: 0px;\n  left: 0px;\n  font-size: 65%;\n  visibility: hidden;\n}\n\n/* Page history styling */\n/* the auto-generated edit comments */\n.mwiki .autocomment {\n  color: gray;\n}\n.mwiki #pagehistory .history-user {\n  margin-left: 0.4em;\n  margin-right: 0.2em;\n}\n.mwiki #pagehistory span.minor {\n  font-weight: bold;\n}\n.mwiki #pagehistory li {\n  border: 1px solid white;\n}\n.mwiki #pagehistory li.selected {\n  background-color: #f9f9f9;\n  border: 1px dashed #aaa;\n}\n\n/*\n * Special:ListGroupRights styling\n * Special:Statistics styling\n*/\n\n.mwiki table.mw-listgrouprights-table,\n.mwiki table.mw-statistics-table {\n  border: 1px solid #ccc;\n  border-collapse: collapse;\n}\n\n.mwiki table.mw-listgrouprights-table tr {\n  vertical-align: top;\n}\n\n.mwiki table.mw-listgrouprights-table td,\n.mwiki table.mw-listgrouprights-table th,\n.mwiki table.mw-statistics-table td,\n.mwiki table.mw-statistics-table th {\n  padding: 0.5em 0.2em 0.5em 0.2em;\n  border: 1px solid #ccc;\n}\n\n.mwiki td.mw-statistics-numbers {\n  text-align: right;\n}\n\n/* Special:SpecialPages styling */\n.mwiki h4.mw-specialpagesgroup {\n  background-color: #dcdcdc;\n  padding: 2px;\n  margin: 0.3em 0em 0em 0em;\n}\n.mwiki .mw-specialpagerestricted {\n  font-weight: bold;\n}\n\n.mwiki #shared-image-dup,\n.mwiki #shared-image-conflict {\n  font-style: italic;\n}\n\n/* Special:EmailUser styling */\n.mwiki table.mw-emailuser-table {\n  width: 98%;\n}\n.mwiki td#mw-emailuser-sender,\n.mwiki td#mw-emailuser-recipient {\n  font-weight: bold;\n}\n\n/* Special:Prefixindex styling */\n.mwiki table#mw-prefixindex-list-table,\n.mwiki table#mw-prefixindex-nav-table {\n  width: 98%;\n  background-color: transparent;\n}\n.mwiki td#mw-prefixindex-nav-form {\n  font-size: smaller;\n  margin-bottom: 1em;\n  text-align: right;\n  vertical-align: top;\n}\n\n/*\n * Recreating deleted page warning\n * Reupload file warning\n * Page protection warning\n * incl. log entries for these warnings\n */\n.mwiki div.mw-warning-with-logexcerpt {\n  padding: 3px;\n  margin-bottom: 3px;\n  border: 2px solid #2f6fab;\n}\n.mwiki div.mw-warning-with-logexcerpt ul li {\n  font-size: 90%;\n}\n\n/* (show/hide) revision deletion links */\n.mwiki span.mw-revdelundel-link,\n.mwiki strong.mw-revdelundel-link {\n  font-family: monospace;\n  font-size: smaller;\n}\n\n/************ monobook/main.css **************/\n\n/*\n** MediaWiki 'monobook' style sheet for CSS2-capable browsers.\n** Copyright Gabriel Wicke - http://wikidev.net/\n** License: GPL (http://www.gnu.org/copyleft/gpl.html)\n**\n** Loosely based on http://www.positioniseverything.net/ordered-floats.html by Big John\n** and the Plone 2.0 styles, see http://plone.org/ (Alexander Limi,Joe Geldart & Tom Croucher,\n** Michael Zeltner and Geir Bækholt)\n** All you guys rock :)\n*/\n\n.mwiki #column-content {\n  width: 100%;\n  float: right;\n  margin: 0 0 0.6em -12.2em;\n  padding: 0;\n}\n.mwiki #content {\n  margin: 2.8em 0 0 12.2em;\n  padding: 0 1em 1em 1em;\n  position: relative;\n  z-index: 2;\n}\n.mwiki #column-one {\n  padding-top: 160px;\n}\n.mwiki #content {\n  background: white;\n  color: black;\n  border: 1px solid #aaa;\n  border-right: none;\n  line-height: 1.5em;\n}\n\n/* scale back up to a sane default */\n.mwiki #globalWrapper {\n  font-size: 127%;\n  width: 100%;\n  margin: 0;\n  padding: 0;\n}\n.mwiki .visualClear {\n  clear: both;\n}\n\n/* general styles */\n\n.mwiki table {\n  font-size: 100%;\n  color: black;\n  /* we don't want the bottom borders of <h2>s to be visible through\n\t   floated tables */\n  background-color: white;\n}\n.mwiki fieldset table {\n  /* but keep table layouts in forms clean... */\n  background: none;\n}\n.mwiki a {\n  text-decoration: none;\n  color: #002bb8;\n  background: none;\n}\n.mwiki a:visited {\n  color: #5a3696;\n}\n.mwiki a:active {\n  color: #faa700;\n}\n.mwiki a:hover {\n  text-decoration: underline;\n}\n.mwiki a.stub {\n  color: #772233;\n}\n.mwiki a.new,\n.mwiki #p-personal a.new {\n  color: #ba0000;\n}\n.mwiki a.new:visited,\n.mwiki #p-personal a.new:visited {\n  color: #a55858;\n}\n\n.mwiki img {\n  border: none;\n  vertical-align: middle;\n}\n.mwiki p {\n  margin: 0.4em 0 0.5em 0;\n  line-height: 1.5em;\n}\n.mwiki p img {\n  margin: 0;\n}\n\n.mwiki hr {\n  height: 1px;\n  color: #aaa;\n  background-color: #aaa;\n  border: 0;\n  margin: 0.2em 0 0.2em 0;\n}\n\n.mwiki h1,\n.mwiki h2,\n.mwiki h3,\n.mwiki h4,\n.mwiki h5,\n.mwiki h6 {\n  color: black;\n  background: none;\n  font-weight: normal;\n  margin: 0;\n  padding-top: 0.5em;\n  padding-bottom: 0.17em;\n  border-bottom: 1px solid #aaa;\n}\n.mwiki h1 {\n  font-size: 188%;\n}\n.mwiki h1 .editsection {\n  font-size: 53%;\n}\n.mwiki h2 {\n  font-size: 150%;\n}\n.mwiki h2 .editsection {\n  font-size: 67%;\n}\n.mwiki h3,\n.mwiki h4,\n.mwiki h5,\n.mwiki h6 {\n  border-bottom: none;\n  font-weight: bold;\n}\n.mwiki h3 {\n  font-size: 132%;\n}\n.mwiki h3 .editsection {\n  font-size: 76%;\n  font-weight: normal;\n}\n.mwiki h4 {\n  font-size: 116%;\n}\n.mwiki h4 .editsection {\n  font-size: 86%;\n  font-weight: normal;\n}\n.mwiki h5 {\n  font-size: 100%;\n}\n.mwiki h5 .editsection {\n  font-weight: normal;\n}\n.mwiki h6 {\n  font-size: 80%;\n}\n.mwiki h6 .editsection {\n  font-size: 125%;\n  font-weight: normal;\n}\n\n.mwiki ul {\n  line-height: 1.5em;\n  list-style-type: square;\n  margin: 0.3em 0 0 1.5em;\n  padding: 0;\n}\n.mwiki ol {\n  line-height: 1.5em;\n  margin: 0.3em 0 0 3.2em;\n  padding: 0;\n  list-style-image: none;\n}\n.mwiki li {\n  margin-bottom: 0.1em;\n}\n.mwiki dt {\n  font-weight: bold;\n  margin-bottom: 0.1em;\n}\n.mwiki dl {\n  margin-top: 0.2em;\n  margin-bottom: 0.5em;\n}\n.mwiki dd {\n  line-height: 1.5em;\n  margin-left: 2em;\n  margin-bottom: 0.1em;\n}\n\n.mwiki fieldset {\n  border: 1px solid #2f6fab;\n  margin: 1em 0 1em 0;\n  padding: 0 1em 1em;\n  line-height: 1.5em;\n}\n.mwiki fieldset.nested {\n  margin: 0 0 0.5em 0;\n  padding: 0 0.5em 0.5em;\n}\n.mwiki legend {\n  padding: 0.5em;\n  font-size: 95%;\n}\n.mwiki form {\n  border: none;\n  margin: 0;\n}\n\n.mwiki textarea {\n  width: 100%;\n  padding: 0.1em;\n}\n\n.mwiki input.historysubmit {\n  padding: 0 0.3em 0.3em 0.3em !important;\n  font-size: 94%;\n  cursor: pointer;\n  height: 1.7em !important;\n  margin-left: 1.6em;\n}\n.mwiki select {\n  vertical-align: top;\n}\n.mwiki abbr,\n.mwiki .explain {\n  border-bottom: 1px dotted black;\n  color: black;\n  background: none;\n  cursor: help;\n}\n.mwiki q {\n  font-family: Times, \"Times New Roman\", serif;\n  font-style: italic;\n}\n/* disabled for now\n.mwiki blockquote {\n\tfont-family: Times, \"Times New Roman\", serif;\n\tfont-style: italic;\n}*/\n.mwiki code {\n  background-color: #f9f9f9;\n}\n.mwiki pre {\n  padding: 1em;\n  border: 1px dashed #2f6fab;\n  color: black;\n  background-color: #f9f9f9;\n  line-height: 1.1em;\n}\n\n/*\n** the main content area\n*/\n\n.mwiki #siteSub {\n  display: none;\n}\n.mwiki #jump-to-nav {\n  display: none;\n}\n\n.mwiki #contentSub,\n.mwiki #contentSub2 {\n  font-size: 84%;\n  line-height: 1.2em;\n  margin: 0 0 1.4em 1em;\n  color: #7d7d7d;\n  width: auto;\n}\n.mwiki span.subpages {\n  display: block;\n}\n\n/* Some space under the headers in the content area */\n.mwiki #bodyContent h1,\n.mwiki #bodyContent h2 {\n  margin-bottom: 0.6em;\n}\n.mwiki #bodyContent h3,\n.mwiki #bodyContent h4,\n.mwiki #bodyContent h5 {\n  margin-bottom: 0.3em;\n}\n.mwiki #firstHeading {\n  margin-bottom: 0.1em;\n  /* These two rules hack around bug 2013 (fix for more limited bug 11325).\n\t   When bug 2013 is fixed properly, they should be removed. */\n  line-height: 1.2em;\n  padding-bottom: 0;\n}\n\n/* user notification thing */\n.mwiki .usermessage {\n  background-color: #ffce7b;\n  border: 1px solid #ffa500;\n  color: black;\n  font-weight: bold;\n  margin: 2em 0 1em;\n  padding: 0.5em 1em;\n  vertical-align: middle;\n}\n.mwiki #siteNotice {\n  text-align: center;\n  font-size: 95%;\n  padding: 0 0.9em;\n}\n.mwiki #siteNotice p {\n  margin: 0;\n  padding: 0;\n}\n.mwiki .success {\n  color: green;\n  font-size: larger;\n}\n.mwiki .error {\n  color: red;\n  font-size: larger;\n}\n.mwiki .errorbox,\n.mwiki .successbox {\n  font-size: larger;\n  border: 2px solid;\n  padding: 0.5em 1em;\n  float: left;\n  margin-bottom: 2em;\n  color: #000;\n}\n.mwiki .errorbox {\n  border-color: red;\n  background-color: #fff2f2;\n}\n.mwiki .successbox {\n  border-color: green;\n  background-color: #dfd;\n}\n.mwiki .errorbox h2,\n.mwiki .successbox h2 {\n  font-size: 1em;\n  font-weight: bold;\n  display: inline;\n  margin: 0 0.5em 0 0;\n  border: none;\n}\n\n.mwiki .catlinks {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  margin-top: 1em;\n  clear: both;\n}\n/* currently unused, intended to be used by a metadata box\nin the bottom-right corner of the content area */\n.mwiki .documentDescription {\n  /* The summary text describing the document */\n  font-weight: bold;\n  display: block;\n  margin: 1em 0;\n  line-height: 1.5em;\n}\n.mwiki .documentByLine {\n  text-align: right;\n  font-size: 90%;\n  clear: both;\n  font-weight: normal;\n  color: #76797c;\n}\n\n/* emulate center */\n.mwiki .center {\n  width: 100%;\n  text-align: center;\n}\n.mwiki *.center * {\n  margin-left: auto;\n  margin-right: auto;\n}\n/* small for tables and similar */\n.mwiki .small,\n.mwiki .small * {\n  font-size: 94%;\n}\n.mwiki table.small {\n  font-size: 100%;\n}\n\n/*\n** content styles\n*/\n\n.mwiki #toc,\n.mwiki .toc,\n.mwiki .mw-warning {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  font-size: 95%;\n}\n.mwiki #toc h2,\n.mwiki .toc h2 {\n  display: inline;\n  border: none;\n  padding: 0;\n  font-size: 100%;\n  font-weight: bold;\n}\n.mwiki #toc #toctitle,\n.mwiki .toc #toctitle,\n.mwiki #toc .toctitle,\n.mwiki .toc .toctitle {\n  text-align: center;\n  position: -webkit-sticky;\n  position: sticky;\n  top: -5px; /* Offset parent's padding */\n  padding: 5px 0;\n  background-color: inherit;\n  z-index: 10;\n}\n\n.mwiki #toc ul,\n.mwiki .toc ul {\n  list-style-type: none;\n  list-style-image: none;\n  margin-left: 0;\n  padding-left: 0;\n  text-align: left;\n}\n.mwiki #toc ul ul,\n.mwiki .toc ul ul {\n  margin: 0 0 0 2em;\n}\n.mwiki #toc .toctoggle,\n.mwiki .toc .toctoggle {\n  font-size: 94%;\n}\n\n/* Bypass toclimit wrapper to ensure sticky positioning works correctly */\n.mwiki div[class*=\"toclimit-\"],\n.mwiki div.tocright {\n  display: contents;\n}\n\n/* Sticky and auto-expanding TOC on hover (Overlay mode) */\n.mwiki #toc,\n.mwiki .toc {\n  position: -webkit-sticky;\n  position: sticky;\n  top: 10px;\n  float: right;\n  z-index: 1000;\n  width: 32px;\n  height: 32px;\n  padding: 0;\n  margin: 0 0 1em 5px;\n  overflow: hidden;\n  opacity: 0.7;\n  background-color: #f8f9fa;\n  border: 1px solid #a2a9b1;\n  border-radius: 4px;\n  transition: opacity 0.3s ease-in-out;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);\n}\n\n.mwiki #toc:hover,\n.mwiki .toc:hover {\n  overflow: visible;\n  opacity: 1;\n}\n\n.mwiki #toc:hover .toctitle,\n.mwiki #toc:hover > ul {\n  display: block;\n  position: absolute;\n  right: 0;\n  width: 280px;\n  background-color: #ffffff;\n  border: 1px solid #a2a9b1;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);\n}\n\n.mwiki #toc:hover .toctitle {\n  top: 0;\n  z-index: 1001;\n  padding: 8px;\n  border-radius: 4px 4px 0 0;\n  text-align: center;\n}\n\n.mwiki #toc:hover > ul {\n  top: 35px;\n  margin: 0;\n  padding: 8px;\n  max-height: 75vh;\n  overflow-y: auto;\n  border-radius: 0 0 4px 4px;\n}\n\n.mwiki #toc ul li {\n  padding: 2px 0;\n  transition: background-color 0.2s;\n}\n\n.mwiki #toc ul li:hover {\n  background-color: rgba(0, 0, 0, 0.05);\n}\n\n.mwiki .mw-warning {\n  margin-left: 50px;\n  margin-right: 50px;\n  text-align: center;\n}\n\n/* images */\n.mwiki div.floatright,\n.mwiki table.floatright {\n  clear: right;\n  float: right;\n  position: relative;\n  margin: 0 0 0.5em 0.5em;\n  border: 0;\n  /*\n\tborder: .5em solid white;\n\tborder-width: .5em 0 .8em 1.4em;\n*/\n}\n.mwiki div.floatright p {\n  font-style: italic;\n}\n.mwiki div.floatleft,\n.mwiki table.floatleft {\n  float: left;\n  clear: left;\n  position: relative;\n  margin: 0 0.5em 0.5em 0;\n  border: 0;\n  /*\n\tmargin: .3em .5em .5em 0;\n\tborder: .5em solid white;\n\tborder-width: .5em 1.4em .8em 0;\n*/\n}\n.mwiki div.floatleft p {\n  font-style: italic;\n}\n/* thumbnails */\n.mwiki div.thumb {\n  margin-bottom: 0.5em;\n  border-style: solid;\n  border-color: white;\n  width: auto;\n}\n.mwiki div.thumbinner {\n  border: 1px solid #ccc;\n  padding: 3px !important;\n  background-color: #f9f9f9;\n  font-size: 94%;\n  text-align: center;\n  overflow: hidden;\n}\n.mwiki html .thumbimage {\n  border: 1px solid #ccc;\n}\n.mwiki html .thumbcaption {\n  border: none;\n  text-align: left;\n  line-height: 1.4em;\n  padding: 3px !important;\n  font-size: 94%;\n}\n.mwiki div.magnify {\n  float: right;\n  border: none !important;\n  background: none !important;\n}\n.mwiki div.magnify a,\n.mwiki div.magnify img {\n  display: block;\n  border: none !important;\n  background: none !important;\n}\n.mwiki div.tright {\n  clear: right;\n  float: right;\n  border-width: 0.5em 0 0.8em 1.4em;\n}\n.mwiki div.tleft {\n  float: left;\n  clear: left;\n  margin-right: 0.5em;\n  border-width: 0.5em 1.4em 0.8em 0;\n}\n.mwiki img.thumbborder {\n  border: 1px solid #dddddd;\n}\n.mwiki .hiddenStructure {\n  display: none;\n}\n\n/*\n** classes for special content elements like town boxes\n** intended to be referenced directly from the wiki src\n*/\n\n/*\n** User styles\n*/\n/* table standards */\n.mwiki table.rimage {\n  float: right;\n  position: relative;\n  margin-left: 1em;\n  margin-bottom: 1em;\n  text-align: center;\n}\n.mwiki .toccolours {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  font-size: 95%;\n}\n\n/*\n** edit views etc\n*/\n.mwiki .special li {\n  line-height: 1.4em;\n  margin: 0;\n  padding: 0;\n}\n\n/*\n** keep the whitespace in front of the ^=, hides rule from konqueror\n** this is css3, the validator doesn't like it when validating as css2\n*/\n\n.mwiki #bodyContent a.external[href$=\".ogg\"],\n.mwiki #bodyContent a.external[href$=\".OGG\"],\n.mwiki #bodyContent a.external[href$=\".oga\"],\n.mwiki #bodyContent a.external[href$=\".OGA\"],\n.mwiki #bodyContent a.external[href$=\".mid\"],\n.mwiki #bodyContent a.external[href$=\".MID\"],\n.mwiki #bodyContent a.external[href$=\".midi\"],\n.mwiki #bodyContent a.external[href$=\".MIDI\"],\n.mwiki #bodyContent a.external[href$=\".mp3\"],\n.mwiki #bodyContent a.external[href$=\".MP3\"],\n.mwiki #bodyContent a.external[href$=\".wav\"],\n.mwiki #bodyContent a.external[href$=\".WAV\"],\n.mwiki #bodyContent a.external[href$=\".wma\"],\n.mwiki #bodyContent a.external[href$=\".WMA\"],\n.mwiki .link-audio {\n  background: url(\"qrc:///icons/audio.png\") center right no-repeat;\n  padding-right: 1em;\n}\n.mwiki #bodyContent a.external[href$=\".ogm\"],\n.mwiki #bodyContent a.external[href$=\".OGM\"],\n.mwiki #bodyContent a.external[href$=\".avi\"],\n.mwiki #bodyContent a.external[href$=\".AVI\"],\n.mwiki #bodyContent a.external[href$=\".mpeg\"],\n.mwiki #bodyContent a.external[href$=\".MPEG\"],\n.mwiki #bodyContent a.external[href$=\".mpg\"],\n.mwiki #bodyContent a.external[href$=\".MPG\"],\n.mwiki .link-video {\n  background: url(\"qrc:///icons/video.svg\") center right no-repeat;\n  padding-right: 1em;\n}\n.mwiki #bodyContent a.external[href$=\".pdf\"],\n.mwiki #bodyContent a.external[href$=\".PDF\"],\n.mwiki #bodyContent a.external[href*=\".pdf#\"],\n.mwiki #bodyContent a.external[href*=\".PDF#\"],\n.mwiki #bodyContent a.external[href*=\".pdf?\"],\n.mwiki #bodyContent a.external[href*=\".PDF?\"],\n.mwiki .link-document {\n  background: url(\"qrc:///icons/document.png\") center right no-repeat;\n  padding-right: 12px;\n}\n\n/* disable interwiki styling */\n.mwiki #bodyContent a.extiw,\n.mwiki #bodyContent a.extiw:active {\n  color: #36b;\n  background: none;\n  padding: 0;\n}\n.mwiki #bodyContent a.external {\n  color: #36b;\n}\n/* this can be used in the content area to switch off\nspecial external link styling */\n.mwiki #bodyContent .plainlinks a {\n  background: none !important;\n  padding: 0 !important;\n}\n/*\n** Structural Elements\n*/\n\n/*\n** general portlet styles (elements in the quickbar)\n*/\n.mwiki .portlet {\n  border: none;\n  margin: 0 0 0.5em;\n  padding: 0;\n  float: none;\n  width: 11.6em;\n  overflow: hidden;\n}\n.mwiki .portlet h4 {\n  font-size: 95%;\n  font-weight: normal;\n  white-space: nowrap;\n}\n.mwiki .portlet h5 {\n  background: transparent;\n  padding: 0 1em 0 0.5em;\n  display: inline;\n  height: 1em;\n  text-transform: lowercase;\n  font-size: 91%;\n  font-weight: normal;\n  white-space: nowrap;\n}\n.mwiki .portlet h6 {\n  background: #ffae2e;\n  border: 1px solid #2f6fab;\n  border-style: solid solid none solid;\n  padding: 0 1em 0 1em;\n  text-transform: lowercase;\n  display: block;\n  font-size: 1em;\n  height: 1.2em;\n  font-weight: normal;\n  white-space: nowrap;\n}\n.mwiki .pBody {\n  font-size: 95%;\n  background-color: white;\n  color: black;\n  border-collapse: collapse;\n  border: 1px solid #aaa;\n  padding: 0 0.8em 0.3em 0.5em;\n}\n.mwiki .portlet h1,\n.mwiki .portlet h2,\n.mwiki .portlet h3,\n.mwiki .portlet h4 {\n  margin: 0;\n  padding: 0;\n}\n.mwiki .portlet ul {\n  line-height: 1.5em;\n  list-style-type: square;\n  font-size: 95%;\n}\n.mwiki .portlet li {\n  padding: 0;\n  margin: 0;\n}\n\n/*\n** Logo properties\n*/\n\n.mwiki #p-logo {\n  top: 0;\n  left: 0;\n  position: absolute; /*needed to use z-index */\n  z-index: 3;\n  height: 155px;\n  width: 12em;\n  overflow: visible;\n}\n.mwiki #p-logo h5 {\n  display: none;\n}\n.mwiki #p-logo a,\n.mwiki #p-logo a:hover {\n  display: block;\n  height: 155px;\n  width: 12.2em;\n  background-repeat: no-repeat;\n  background-position: 35% 50% !important;\n  text-decoration: none;\n}\n\n/*\n** Search portlet\n*/\n.mwiki #p-search {\n  position: relative;\n  z-index: 3;\n}\n.mwiki input.searchButton {\n  margin-top: 1px;\n  font-size: 95%;\n}\n.mwiki #searchGoButton {\n  padding-left: 0.5em;\n  padding-right: 0.5em;\n  font-weight: bold;\n}\n.mwiki #searchInput {\n  width: 10.9em;\n  margin: 0;\n  font-size: 95%;\n}\n.mwiki #p-search .pBody {\n  padding: 0.5em 0.4em 0.4em 0.4em;\n  text-align: center;\n}\n.mwiki #p-search #searchform div div {\n  margin-top: 0.4em;\n  font-size: 95%;\n}\n/*\n** the personal toolbar\n*/\n.mwiki #p-personal {\n  position: absolute;\n  left: 0;\n  top: 0;\n  z-index: 0;\n}\n.mwiki #p-personal {\n  width: 100%;\n  white-space: nowrap;\n  padding: 0;\n  margin: 0;\n  border: none;\n  background: none;\n  overflow: visible;\n  line-height: 1.2em;\n}\n.mwiki #p-personal h5 {\n  display: none;\n}\n.mwiki #p-personal .portlet,\n.mwiki #p-personal .pBody {\n  z-index: 0;\n  padding: 0;\n  margin: 0;\n  border: none;\n  overflow: visible;\n  background: none;\n}\n/* this is the ul contained in the portlet */\n.mwiki #p-personal ul {\n  border: none;\n  line-height: 1.4em;\n  color: #2f6fab;\n  padding: 0 2em 0 3em;\n  margin: 0;\n  text-align: right;\n  list-style: none;\n  z-index: 0;\n  background: none;\n  cursor: default;\n}\n.mwiki #p-personal li {\n  z-index: 0;\n  border: none;\n  padding: 0;\n  display: inline;\n  color: #2f6fab;\n  margin-left: 1em;\n  line-height: 1.2em;\n  background: none;\n}\n.mwiki #p-personal li a {\n  text-decoration: none;\n  color: #005896;\n  padding-bottom: 0.2em;\n  background: none;\n}\n.mwiki #p-personal li a:hover {\n  background-color: white;\n  padding-bottom: 0.2em;\n  text-decoration: none;\n}\n.mwiki #p-personal li.active a:hover {\n  background-color: transparent;\n}\n/* the icon in front of the user name, single quotes\nin bg url to hide it from iemac */\n.mwiki li#pt-userpage,\n.mwiki li#pt-anonuserpage,\n.mwiki li#pt-login {\n  padding-left: 20px;\n  text-transform: none;\n}\n.mwiki #p-personal ul {\n  text-transform: lowercase;\n}\n.mwiki #p-personal li.active {\n  font-weight: bold;\n}\n/*\n** the page-related actions- page/talk, edit etc\n*/\n.mwiki #p-cactions {\n  position: absolute;\n  top: 1.3em;\n  left: 11.5em;\n  margin: 0;\n  white-space: nowrap;\n  width: 76%;\n  line-height: 1.1em;\n  overflow: visible;\n  background: none;\n  border-collapse: collapse;\n  padding-left: 1em;\n  list-style: none;\n  font-size: 95%;\n}\n.mwiki #p-cactions ul {\n  list-style: none;\n}\n.mwiki #p-cactions li {\n  display: inline;\n  border: 1px solid #aaa;\n  border-bottom: none;\n  padding: 0 0 0.1em 0;\n  margin: 0 0.3em 0 0;\n  overflow: visible;\n  background: white;\n}\n.mwiki #p-cactions li.selected {\n  border-color: #fabd23;\n  padding: 0 0 0.2em 0;\n  font-weight: bold;\n}\n.mwiki #p-cactions li a {\n  background-color: #fbfbfb;\n  color: #002bb8;\n  border: none;\n  padding: 0 0.8em 0.3em;\n  position: relative;\n  z-index: 0;\n  margin: 0;\n  text-decoration: none;\n}\n.mwiki #p-cactions li.selected a {\n  z-index: 3;\n  padding: 0 1em 0.2em !important;\n  background-color: white;\n}\n.mwiki #p-cactions .new a {\n  color: #ba0000;\n}\n.mwiki #p-cactions li a:hover {\n  z-index: 3;\n  text-decoration: none;\n  background-color: white;\n}\n.mwiki #p-cactions h5 {\n  display: none;\n}\n.mwiki #p-cactions li.istalk {\n  margin-right: 0;\n}\n.mwiki #p-cactions li.istalk a {\n  padding-right: 0.5em;\n}\n.mwiki #p-cactions #ca-addsection a {\n  padding-left: 0.4em;\n  padding-right: 0.4em;\n}\n/* offsets to distinguish the tab groups */\n.mwiki li#ca-talk {\n  margin-right: 1.6em;\n}\n.mwiki li#ca-watch,\n.mwiki li#ca-unwatch,\n.mwiki li#ca-varlang-0,\n.mwiki li#ca-print {\n  margin-left: 1.6em;\n}\n.mwiki #p-cactions .pBody {\n  font-size: 1em;\n  background-color: transparent;\n  color: inherit;\n  border-collapse: inherit;\n  border: 0;\n  padding: 0;\n}\n.mwiki #p-cactions .hiddenStructure {\n  display: none;\n}\n.mwiki #p-cactions li a {\n  text-transform: lowercase;\n}\n\n.mwiki #p-lang {\n  position: relative;\n  z-index: 3;\n}\n\n/* #t-iscite is only used by the Cite extension, come up with some\n * system which allows extensions to add to this file on the fly\n */\n.mwiki #t-ispermalink,\n.mwiki #t-iscite {\n  color: #999;\n}\n/*\n** footer\n*/\n.mwiki #footer {\n  background-color: white;\n  border-top: 1px solid #fabd23;\n  border-bottom: 1px solid #fabd23;\n  margin: 0.6em 0 1em 0;\n  padding: 0.4em 0 1.2em 0;\n  text-align: center;\n  font-size: 90%;\n}\n.mwiki #footer li {\n  display: inline;\n  margin: 0 1.3em;\n}\n.mwiki #f-poweredbyico,\n.mwiki #f-copyrightico {\n  margin: 0 8px;\n  position: relative;\n  top: -2px; /* Bump it up just a tad */\n}\n.mwiki #f-poweredbyico {\n  float: right;\n  height: 1%;\n}\n.mwiki #f-copyrightico {\n  float: left;\n  height: 1%;\n}\n\n/* js pref toc */\n.mwiki #preftoc {\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  clear: both;\n}\n.mwiki #preftoc li {\n  background-color: #f0f0f0;\n  color: #000;\n}\n.mwiki #preftoc li {\n  margin: 1px -2px 1px 2px;\n  float: left;\n  padding: 2px 0 3px 0;\n  border: 1px solid #fff;\n  border-right-color: #716f64;\n  border-bottom: 0;\n  position: relative;\n  white-space: nowrap;\n  list-style-type: none;\n  list-style-image: none;\n  z-index: 3;\n}\n.mwiki #preftoc li.selected {\n  font-weight: bold;\n  background-color: #f9f9f9;\n  border: 1px solid #aaa;\n  border-bottom: none;\n  cursor: default;\n  top: 1px;\n  padding-top: 2px;\n  margin-right: -3px;\n}\n.mwiki #preftoc > li.selected {\n  top: 2px;\n}\n.mwiki #preftoc a,\n.mwiki #preftoc a:active {\n  display: block;\n  color: #000;\n  padding: 0 0.7em;\n  position: relative;\n  text-decoration: none;\n}\n.mwiki #preftoc li.selected a {\n  cursor: default;\n  text-decoration: none;\n}\n.mwiki #prefcontrol {\n  padding-top: 2em;\n  clear: both;\n}\n.mwiki #preferences {\n  margin: 0;\n  border: 1px solid #aaa;\n  clear: both;\n  padding: 1.5em;\n  background-color: #f9f9f9;\n}\n.mwiki .prefsection {\n  border: none;\n  padding: 0;\n  margin: 0;\n}\n.mwiki .prefsection fieldset {\n  border: 1px solid #aaa;\n  float: left;\n  margin-right: 2em;\n}\n.mwiki .prefsection legend {\n  font-weight: bold;\n}\n.mwiki .prefsection table,\n.mwiki .prefsection legend {\n  background-color: #f9f9f9;\n}\n.mwiki .mainLegend {\n  display: none;\n}\n.mwiki div.prefsectiontip {\n  font-size: x-small;\n  padding: 0.2em 2em;\n  color: #666;\n}\n.mwiki .btnSavePrefs {\n  font-weight: bold;\n  padding-left: 0.3em;\n  padding-right: 0.3em;\n}\n\n.mwiki .preferences-login {\n  clear: both;\n  margin-bottom: 1.5em;\n}\n\n.mwiki .prefcache {\n  font-size: 90%;\n  margin-top: 2em;\n}\n\n.mwiki div#userloginForm form,\n.mwiki div#userlogin form#userlogin2 {\n  margin: 0 3em 1em 0;\n  border: 1px solid #aaa;\n  clear: both;\n  padding: 1.5em 2em;\n  background-color: #f9f9f9;\n  float: left;\n}\n.mwiki .rtl div#userloginForm form,\n.mwiki .rtl div#userlogin form#userlogin2 {\n  float: right;\n}\n\n.mwiki div#userloginForm table,\n.mwiki div#userlogin form#userlogin2 table {\n  background-color: #f9f9f9;\n}\n\n.mwiki div#userloginForm h2,\n.mwiki div#userlogin form#userlogin2 h2 {\n  padding-top: 0;\n}\n\n.mwiki div#userlogin .captcha,\n.mwiki div#userloginForm .captcha {\n  border: 1px solid #bbb;\n  padding: 1.5em 2em;\n  background-color: white;\n}\n\n.mwiki #loginend,\n.mwiki #signupend {\n  clear: both;\n}\n\n.mwiki #userloginprompt,\n.mwiki #languagelinks {\n  font-size: 85%;\n}\n\n.mwiki #login-sectiontip {\n  font-size: 85%;\n  line-height: 1.2;\n  padding-top: 2em;\n}\n\n.mwiki #userlogin .loginText,\n.mwiki #userlogin .loginPassword {\n  width: 12em;\n}\n\n.mwiki #userloginlink a,\n.mwiki #wpLoginattempt,\n.mwiki #wpCreateaccount {\n  font-weight: bold;\n}\n\n/* IE/Mac fixes were cut out */\n\n.mwiki .redirectText {\n  font-size: 150%;\n  margin: 5px;\n}\n\n.mwiki .printfooter {\n  display: none;\n}\n\n.mwiki .not-patrolled {\n  background-color: #ffa;\n}\n.mwiki div.patrollink {\n  clear: both;\n  font-size: 75%;\n  text-align: right;\n}\n.mwiki span.newpage,\n.mwiki span.minor,\n.mwiki span.bot {\n  font-weight: bold;\n}\n.mwiki span.unpatrolled {\n  font-weight: bold;\n  color: red;\n}\n\n.mwiki .sharedUploadNotice {\n  font-style: italic;\n}\n\n.mwiki span.updatedmarker {\n  color: black;\n  background-color: #0f0;\n}\n\n.mwiki table.gallery {\n  border: 1px solid #ccc;\n  margin: 2px;\n  padding: 2px;\n  background-color: white;\n}\n\n.mwiki table.gallery tr {\n  vertical-align: top;\n}\n\n.mwiki table.gallery td {\n  vertical-align: top;\n  background-color: #f9f9f9;\n  border: solid 2px white;\n}\n/* Keep this temporarily so that cached pages will display right */\n.mwiki table.gallery td.galleryheader {\n  text-align: center;\n  font-weight: bold;\n}\n.mwiki table.gallery caption {\n  font-weight: bold;\n}\n\n.mwiki div.gallerybox {\n  margin: 2px;\n}\n\n.mwiki div.gallerybox div.thumb {\n  text-align: center;\n  border: 1px solid #ccc;\n  margin: 2px;\n}\n\n.mwiki div.gallerytext {\n  overflow: hidden;\n  font-size: 94%;\n  padding: 2px 4px;\n}\n\n.mwiki span.comment {\n  font-style: italic;\n}\n\n.mwiki span.changedby {\n  font-size: 95%;\n}\n\n.mwiki .previewnote {\n  text-indent: 3em;\n  color: #c00;\n  border-bottom: 1px solid #aaa;\n  padding-bottom: 1em;\n  margin-bottom: 1em;\n}\n\n.mwiki .previewnote p {\n  margin: 0;\n  padding: 0;\n}\n\n.mwiki .editExternally {\n  border: 1px solid gray;\n  background-color: #ffffff;\n  padding: 3px;\n  margin-top: 0.5em;\n  float: left;\n  font-size: small;\n  text-align: center;\n}\n.mwiki .editExternallyHelp {\n  font-style: italic;\n  color: gray;\n}\n\n.mwiki .toggle {\n  margin-left: 2em;\n  text-indent: -2em;\n}\n\n/* Classes for EXIF data display */\n.mwiki table.mw_metadata {\n  font-size: 0.8em;\n  margin-left: 0.5em;\n  margin-bottom: 0.5em;\n  width: 300px;\n}\n\n.mwiki table.mw_metadata caption {\n  font-weight: bold;\n}\n\n.mwiki table.mw_metadata th {\n  font-weight: normal;\n}\n\n.mwiki table.mw_metadata td {\n  padding: 0.1em;\n}\n\n.mwiki table.mw_metadata {\n  border: none;\n  border-collapse: collapse;\n}\n\n.mwiki table.mw_metadata td,\n.mwiki table.mw_metadata th {\n  text-align: center;\n  border: 1px solid #aaaaaa;\n  padding-left: 0.1em;\n  padding-right: 0.1em;\n}\n\n.mwiki table.mw_metadata th {\n  background-color: #f9f9f9;\n}\n\n.mwiki table.mw_metadata td {\n  background-color: #fcfcfc;\n}\n\n.mwiki table.collapsed tr.collapsable {\n  display: none;\n}\n\n/* filetoc */\n.mwiki ul#filetoc {\n  text-align: center;\n  border: 1px solid #aaaaaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  font-size: 95%;\n  margin-bottom: 0.5em;\n  margin-left: 0;\n  margin-right: 0;\n}\n\n.mwiki #filetoc li {\n  display: inline;\n  list-style-type: none;\n  padding-right: 2em;\n}\n\n.mwiki input#wpSummary {\n  width: 80%;\n}\n\n/* @bug 1714 */\n.mwiki input#wpSave,\n.mwiki input#wpDiff {\n  margin-right: 0.33em;\n}\n\n.mwiki #wpSave {\n  font-weight: bold;\n}\n\n/* Classes for article validation */\n\n.mwiki table.revisionform_default {\n  border: 1px solid #000000;\n}\n\n.mwiki table.revisionform_focus {\n  border: 1px solid #000000;\n  background-color: #00bbff;\n}\n\n.mwiki tr.revision_tr_default {\n  background-color: #eeeeee;\n}\n\n.mwiki tr.revision_tr_first {\n  background-color: #dddddd;\n}\n\n.mwiki p.revision_saved {\n  color: green;\n  font-weight: bold;\n}\n\n.mwiki #mw_trackbacks {\n  border: solid 1px #bbbbff;\n  background-color: #eeeeff;\n  padding: 0.2em;\n}\n\n/* Allmessages table */\n\n.mwiki #allmessagestable th {\n  background-color: #b2b2ff;\n}\n\n.mwiki #allmessagestable tr.orig {\n  background-color: #ffe2e2;\n}\n\n.mwiki #allmessagestable tr.new {\n  background-color: #e2ffe2;\n}\n\n.mwiki #allmessagestable tr.def {\n  background-color: #f0f0ff;\n}\n\n/* noarticletext */\n.mwiki div.noarticletext {\n  border: 1px solid #ccc;\n  background: #fff;\n  padding: 0.2em 1em;\n  color: #000;\n}\n\n.mwiki div#searchTargetContainer {\n  left: 10px;\n  top: 10px;\n  width: 90%;\n  background: white;\n}\n\n.mwiki div#searchTarget {\n  padding: 3px;\n  margin: 5px;\n  background: #f0f0f0;\n  border: solid 1px blue;\n}\n\n.mwiki div#searchTarget ul li {\n  list-style: none;\n}\n\n.mwiki div#searchTarget ul li:before {\n  color: orange;\n  content: \"\\00BB \\0020\";\n}\n\n.mwiki div#searchTargetHide {\n  float: right;\n  border: solid 1px black;\n  background: #dcdcdc;\n  padding: 2px;\n}\n\n.mwiki #powersearch p {\n  margin-top: 0px;\n}\n\n.mwiki div.multipageimagenavbox {\n  border: solid 1px silver;\n  padding: 4px;\n  margin: 1em;\n  background: #f0f0f0;\n}\n\n.mwiki div.multipageimagenavbox div.thumb {\n  border: none;\n  margin-left: 2em;\n  margin-right: 2em;\n}\n\n.mwiki div.multipageimagenavbox hr {\n  margin: 6px;\n}\n\n.mwiki table.multipageimage td {\n  text-align: center;\n}\n\n/** Special:Version */\n\n.mwiki table#sv-ext,\ntable#sv-hooks,\n.mwiki table#sv-software {\n  margin: 1em;\n  padding: 0em;\n}\n\n.mwiki #sv-ext td,\n.mwiki #sv-hooks td,\n.mwiki #sv-software td,\n.mwiki #sv-ext th,\n.mwiki #sv-hooks th,\n.mwiki #sv-software th {\n  border: 1px solid #a0a0a0;\n  padding: 0 0.15em 0 0.15em;\n}\n.mwiki #sv-ext th,\n.mwiki #sv-hooks th,\n.mwiki #sv-software th {\n  background-color: #f0f0f0;\n  color: black;\n  padding: 0 0.15em 0 0.15em;\n}\n.mwiki tr.sv-space {\n  height: 0.8em;\n  border: none;\n}\n.mwiki tr.sv-space td {\n  display: none;\n}\n\n/*\n  Table pager (e.g. Special:Imagelist)\n  - remove underlines from the navigation link\n  - collapse borders\n  - set the borders to outsets (similar to Special:Allmessages)\n  - remove line wrapping for all td and th, set background color\n  - restore line wrapping for the last two table cells (description and size)\n*/\n.mwiki .TablePager {\n  min-width: 80%;\n}\n.mwiki .TablePager_nav a {\n  text-decoration: none;\n}\n.mwiki .TablePager {\n  border-collapse: collapse;\n}\n.mwiki .TablePager,\n.mwiki .TablePager td,\n.mwiki .TablePager th {\n  border: 1px solid #aaaaaa;\n  padding: 0 0.15em 0 0.15em;\n}\n.mwiki .TablePager th {\n  background-color: #eeeeff;\n}\n.mwiki .TablePager td {\n  background-color: #ffffff;\n}\n.mwiki .TablePager tr:hover td {\n  background-color: #eeeeff;\n}\n\n.mwiki .imagelist td,\n.mwiki .imagelist th {\n  white-space: nowrap;\n}\n.mwiki .imagelist .TablePager_col_links {\n  background-color: #eeeeff;\n}\n.mwiki .imagelist .TablePager_col_img_description {\n  white-space: normal;\n}\n.mwiki .imagelist th.TablePager_sort {\n  background-color: #ccccff;\n}\n\n.mwiki .templatesUsed {\n  margin-top: 1.5em;\n}\n\n.mwiki .mw-summary-preview {\n  margin: 0.1em 0;\n}\n\n/* Friendlier slave lag warnings */\n.mwiki div.mw-lag-warn-normal,\n.mwiki div.mw-lag-warn-high {\n  padding: 3px;\n  text-align: center;\n  margin: 3px auto;\n}\n.mwiki div.mw-lag-warn-normal {\n  border: 1px solid #ffcc66;\n  background-color: #ffffcc;\n}\n.mwiki div.mw-lag-warn-high {\n  font-weight: bold;\n  border: 2px solid #ff0033;\n  background-color: #ffcccc;\n}\n\n.mwiki .MediaTransformError {\n  background-color: #ccc;\n  padding: 0.1em;\n}\n.mwiki .MediaTransformError td {\n  text-align: center;\n  vertical-align: middle;\n  font-size: 90%;\n}\n\n/** Special:Search stuff */\n.mwiki div#mw-search-interwiki-caption {\n  text-align: center;\n  font-weight: bold;\n  font-size: 95%;\n}\n\n.mwiki .mw-search-interwiki-project {\n  font-size: 97%;\n  text-align: left;\n  padding-left: 0.2em;\n  padding-right: 0.15em;\n  padding-bottom: 0.2em;\n  padding-top: 0.15em;\n  background: #cae8ff;\n}\n\n/* God-damned hack for the crappy layout */\n.mwiki .os-suggest {\n  font-size: 127%;\n}\n\n/**** Excerpts from http://en.wikipedia.org/wiki/MediaWiki:Common.css ******/\n/* Since GoldenDict support is not Wikipedia-specific, we don't include all\n * of it, and besides, it's large and volatile anyway. */\n/* It was also edited for the usually narrow article view */\n\n/* Make the list of references smaller */\n.mwiki ol.references {\n  font-size: 100%;\n}\n.mwiki .references-small {\n  font-size: 90%;\n}\n\n.mwiki .references-2column {\n  font-size: 90%;\n  column-count: 2;\n}\n\n/* Highlight clicked reference in blue to help navigation */\n.mwiki ol.references > li:target {\n  background-color: #def;\n}\n\n.mwiki sup.reference:target {\n  background-color: #def;\n}\n\n/* Styling for citations */\n.mwiki cite {\n  font-style: normal;\n  word-wrap: break-word;\n}\n\n/* If there is an inline link to a full citation, the full citation will turn blue when the inline link is clicked */\n.mwiki cite:target {\n  background-color: #def;\n}\n\n/* wikitable/prettytable class for skinning normal tables */\n.mwiki table.wikitable,\n.mwiki table.prettytable {\n  margin: 1em 1em 1em 0;\n  background: #f9f9f9;\n  border: 1px #aaa solid;\n  border-collapse: collapse;\n}\n.mwiki .wikitable th,\n.mwiki .wikitable td,\n.mwiki .prettytable th,\n.mwiki .prettytable td {\n  border: 1px #aaa solid;\n  padding: 0.2em;\n}\n.mwiki .wikitable th,\n.mwiki .prettytable th {\n  background: #f2f2f2;\n  text-align: center;\n}\n.mwiki .wikitable caption,\n.mwiki .prettytable caption {\n  font-weight: bold;\n}\n\n/* default skin for navigation boxes */\n.mwiki table.navbox {\n  /* navbox container style */\n  border: 1px solid #aaa;\n  width: 100%;\n  margin: auto;\n  clear: both;\n  font-size: 88%;\n  text-align: center;\n  padding: 1px;\n}\n.mwiki table.navbox + table.navbox {\n  margin-top: -1px; /* single pixel border between adjacent navboxes (doesn't work for IE6, but that's okay) */\n}\n.mwiki .navbox-title,\n.mwiki .navbox-abovebelow,\n.mwiki table.navbox th {\n  text-align: center; /* title and above/below styles */\n  padding-left: 1em;\n  padding-right: 1em;\n}\n.mwiki .navbox-group {\n  /* group style */\n  white-space: nowrap;\n  text-align: right;\n  font-weight: bold;\n  padding-left: 1em;\n  padding-right: 1em;\n}\n.mwiki .navbox,\n.mwiki .navbox-subgroup {\n  background: #fdfdfd; /* Background color */\n}\n.mwiki .navbox-list {\n  border-color: #fdfdfd; /* Must match background color */\n}\n.mwiki .navbox-title,\n.mwiki table.navbox th {\n  background: #ccccff; /* Level 1 color */\n}\n.mwiki .navbox-abovebelow,\n.mwiki .navbox-group,\n.mwiki .navbox-subgroup .navbox-title {\n  background: #ddddff; /* Level 2 color */\n}\n.mwiki .navbox-subgroup .navbox-group,\n.mwiki .navbox-subgroup .navbox-abovebelow {\n  background: #e6e6ff; /* Level 3 color */\n}\n.mwiki .navbox-even {\n  background: #f7f7f7; /* Even row striping */\n}\n.mwiki .navbox-odd {\n  background: transparent; /* Odd row striping */\n}\n\n.mwiki .collapseButton {\n  /* 'show'/'hide' buttons created dynamically by the        */\n  float: right; /* CollapsibleTables javascript in [[MediaWiki:Common.js]] */\n  font-weight: normal; /* are styled here so they can be customised.              */\n  text-align: right;\n  width: auto;\n}\n.mwiki .navbox .collapseButton {\n  /* In navboxes, the show/hide button balances the vde links from */\n  width: 6em; /* [[Template:Tnavbar]], so they need to be the same width.      */\n}\n\n/* Infobox template style */\n.mwiki .infobox {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  color: black;\n  /*    margin: 0.5em 0 0.5em 1em;*/\n  margin: 10px auto 0;\n  padding: 0.2em;\n  /*\n    float: right;\n    clear: right;*/\n}\n\n.mwiki .infobox td,\n.mwiki .infobox th {\n  vertical-align: top;\n}\n.mwiki .infobox caption {\n  font-size: larger;\n}\n.mwiki .infobox.bordered {\n  border-collapse: collapse;\n}\n.mwiki .infobox.bordered td,\n.mwiki .infobox.bordered th {\n  border: 1px solid #aaa;\n}\n.mwiki .infobox.bordered .borderless td,\n.mwiki .infobox.bordered .borderless th {\n  border: 0;\n}\n\n.mwiki .infobox.sisterproject {\n  width: 20em;\n  font-size: 90%;\n}\n\n.mwiki .infobox.standard-talk {\n  border: 1px solid #c0c090;\n  background-color: #f8eaba;\n}\n.mwiki .infobox.standard-talk.bordered td,\n.mwiki .infobox.standard-talk.bordered th {\n  border: 1px solid #c0c090;\n}\n\n/* styles for bordered infobox with merged rows */\n.mwiki .infobox.bordered .mergedtoprow td,\n.mwiki .infobox.bordered .mergedtoprow th {\n  border: 0;\n  border-top: 1px solid #aaa;\n  border-right: 1px solid #aaa;\n}\n\n.mwiki .infobox.bordered .mergedrow td,\n.mwiki .infobox.bordered .mergedrow th {\n  border: 0;\n  border-right: 1px solid #aaa;\n}\n\n/* Styles for geography infoboxes, e.g. countries, country subdivisions, cities, etc. */\n.mwiki .infobox.geography {\n  text-align: left;\n  border-collapse: collapse;\n  line-height: 1.2em;\n  font-size: 90%;\n}\n\n.mwiki .infobox.geography td,\n.mwiki .infobox.geography th {\n  border-top: solid 1px #aaa;\n  padding: 0.4em 0.6em 0.4em 0.6em;\n}\n.mwiki .infobox.geography .mergedtoprow td,\n.mwiki .infobox.geography .mergedtoprow th {\n  border-top: solid 1px #aaa;\n  padding: 0.4em 0.6em 0.2em 0.6em;\n}\n\n.mwiki .infobox.geography .mergedrow td,\n.mwiki .infobox.geography .mergedrow th {\n  border: 0;\n  padding: 0 0.6em 0.2em 0.6em;\n}\n\n.mwiki .infobox.geography .mergedbottomrow td,\n.mwiki .infobox.geography .mergedbottomrow th {\n  border-top: 0;\n  border-bottom: solid 1px #aaa;\n  padding: 0 0.6em 0.4em 0.6em;\n}\n\n.mwiki .infobox.geography .maptable td,\n.mwiki .infobox.geography .maptable th {\n  border: 0;\n  padding: 0;\n}\n\n/* Style for \"notices\" */\n.mwiki .notice {\n  margin: 1em;\n  padding: 0.2em;\n}\n\n.mwiki #disambig {\n  border-top: 1px solid #ccc;\n  border-bottom: 1px solid #ccc;\n}\n\n.mwiki .rellink,\n.mwiki .dablink {\n  font-style: italic;\n  padding-left: 2em;\n}\n.mwiki .rellink i,\n.mwiki .dablink i {\n  font-style: normal;\n}\n\n/* Article message box styles */\n.mwiki table.ambox {\n  /* 10% = Will not overlap with other elements */\n  margin: -1px 10% 0px; /* -1px = Single border between stacked boxes in all browsers */\n  border: 1px solid #aaa;\n  border-left: 10px solid #1e90ff; /* Default \"notice\" blue */\n  background: #fbfbfb;\n}\n.mwiki .ambox th.mbox-text,\n.mwiki .ambox td.mbox-text {\n  /* The message body cell(s) */\n  padding: 0.25em 0.5em; /* 0.5em left/right */\n}\n.mwiki .ambox td.mbox-image {\n  /* The left image cell */\n  padding: 2px 0 2px 0.5em; /* 0.5em left, 0px right */\n}\n.mwiki .ambox td.mbox-imageright {\n  /* The right image cell */\n  padding: 2px 0.5em 2px 0; /* 0px left, 0.5em right */\n}\n\n/* Standard Navigationsleisten, aka box hiding thingy from .de.  Documentation at [[Wikipedia:NavFrame]]. */\n.mwiki div.NavFrame {\n  margin: 0;\n  padding: 4px;\n  border: 1px solid #aaa;\n  text-align: center;\n  border-collapse: collapse;\n  font-size: 95%;\n}\n.mwiki div.NavFrame + div.NavFrame {\n  border-top-style: none;\n  border-top-style: hidden;\n}\n.mwiki div.NavPic {\n  background-color: #fff;\n  margin: 0;\n  padding: 2px;\n  float: left;\n}\n.mwiki div.NavFrame div.NavHead {\n  height: 1.6em;\n  font-weight: bold;\n  background-color: #ccf;\n  position: relative;\n}\n.mwiki div.NavFrame p {\n  font-size: 100%;\n}\n.mwiki div.NavFrame div.NavContent {\n  font-size: 100%;\n}\n.mwiki div.NavFrame div.NavContent p {\n  font-size: 100%;\n}\n.mwiki div.NavEnd {\n  margin: 0;\n  padding: 0;\n  line-height: 1px;\n  clear: both;\n}\n.mwiki a.NavToggle {\n  position: absolute;\n  top: 0;\n  right: 3px;\n  font-weight: normal;\n  font-size: 90%;\n}\n\n/****** Wiktionary-specific excerpts *********/\n\n.mwiki .audiolink a {\n  background: url(\"qrc:///icons/audio.png\") center left no-repeat !important;\n  padding-left: 20px !important;\n  padding-right: 0 !important;\n}\n\n/* default setting for [[:Category:Inflection templates]] */\n\n.mwiki .infl-inline {\n  display: inline;\n}\n.mwiki .infl-table {\n  display: none;\n}\n\n.gddicticon {\n  display: none;\n}\n\n.gddicticon img {\n  height: 1rem;\n}\n\n.gdexpandicon {\n  cursor: pointer;\n  width: 1rem;\n  height: 1rem;\n  vertical-align: text-bottom;\n  content: url(\"qrc:///icons/arrow.svg\");\n}\n\n.gdcollapseicon {\n  cursor: pointer;\n  width: 1rem;\n  height: 1rem;\n  vertical-align: text-bottom;\n  content: url(\"qrc:///icons/downarrow.svg\");\n}\n\n.gdexpandicon:focus,\n.gdcollapseicon:focus {\n  outline: 2px solid var(--link-color);\n  outline-offset: 2px;\n}\n\n/********** Slob dictionaries ***********/\n\n.slobdict_headword {\n  display: none;\n}\n\n.slobdict img.imgtex {\n  vertical-align: baseline !important;\n}\n\n/************* Welcome Page **************/\n\n.welcome-container {\n  max-width: 850px;\n  margin: 2em auto;\n  padding: 1.5em 2em;\n  line-height: 1.7;\n  color: var(--text-color);\n  /* Optional: background and border-radius for a card-like look */\n  /* background-color: var(--container-bg); */\n  /* border-radius: 8px; */\n}\n.welcome-container h3,\n.welcome-container h4 {\n  text-align: center;\n  margin-bottom: 1em;\n}\n.welcome-container h3 {\n  font-size: 1.6em;\n  font-weight: 600;\n}\n.welcome-container h4 {\n  font-size: 1.2em;\n  font-weight: 500;\n  margin-top: 2em;\n}\n.welcome-container p,\n.welcome-container ul {\n  margin-bottom: 1.2em;\n}\n.welcome-container ul {\n  list-style: none;\n  padding-left: 20px;\n}\n.welcome-container li {\n  margin-bottom: 0.5em;\n  position: relative;\n  padding-left: 25px;\n}\n.welcome-container li::before {\n  content: \"✓\";\n  position: absolute;\n  left: 0;\n  color: var(--link-color);\n}\n.welcome-container a {\n  color: var(--link-color);\n  text-decoration: none;\n  transition: color 0.2s;\n}\n.welcome-container a:hover {\n  text-decoration: underline;\n}\n.welcome-footer {\n  margin-top: 2.5em;\n  text-align: center;\n  font-size: 0.85em;\n  color: var(--secondary-text-color);\n}\n\n.menu-path > span {\n  --menu-path-text-color: #3b5998;\n  --menu-path-arrow-color: #8b9dc3;\n  font-weight: 600;\n  font-style: normal;\n  color: var(--menu-path-text-color);\n}\n.menu-path > span + span::before {\n  content: \"\";\n  display: inline-block;\n  width: 1em;\n  height: 1em;\n  margin: 0 0.3em;\n  vertical-align: -0.15em;\n  background-color: var(--menu-path-arrow-color);\n  -webkit-mask-image: url('data:image/svg+xml;utf8,<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"black\"><path d=\"M10 6L8.59 7.41L13.17 12l-4.58 4.59L10 18l6-6z\"/></svg>');\n  mask-image: url('data:image/svg+xml;utf8,<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"black\"><path d=\"M10 6L8.59 7.41L13.17 12l-4.58 4.59L10 18l6-6z\"/></svg>');\n}\n/************* GLS dictionaries **************/\n\n.glsdict_headwords {\n  font-weight: bold;\n  margin-top: 15px;\n  margin-bottom: 10px;\n  font-size: 116%;\n}\n\n.gls_wav img {\n  vertical-align: middle;\n}\n","article-style-print.css":"/* This stylesheet is used for printing only, overriding article-style.css */\n\n@page {\n  size: auto;\n  margin: 1.5cm;\n}\n\nhtml,\nbody {\n  background: white !important;\n  color: black !important;\n  margin: 0; /* Let @page or browser handle margins */\n  padding: 0;\n}\n\nbody {\n  /* Fallback margin for engines that ignore @page */\n  margin: 1.5cm;\n}\n\n.gdarticle {\n  background: white !important;\n  color: black !important;\n  text-align: justify;\n}\n\n/* Hide audio icons */\n\n.dsl_s_wav {\n  display: none;\n}\n\n/* hide collapse area*/\n\n.collapse_expand_area {\n  display: none;\n}\n\n/* Hide edit links and other UI elements for printing */\n.mwiki .editsection,\n.mwiki .mw-editsection,\n.mwiki .toctoggle,\n.mwiki .magnify {\n  display: none !important;\n}\n\n/* Reset MediaWiki TOC for printing */\n.mwiki #toc,\n.mwiki .toc {\n  display: block !important;\n  position: static !important;\n  width: 100% !important;\n  box-sizing: border-box !important;\n  height: auto !important;\n  max-height: none !important;\n  max-width: none !important;\n  opacity: 1 !important;\n  overflow: visible !important;\n  float: none !important;\n  clear: both !important;\n  margin: 1em 0 !important;\n  box-shadow: none !important;\n  border: none !important;\n}\n\n.mwiki #toc .toctitle,\n.mwiki .toc .toctitle,\n.mwiki #toc ul,\n.mwiki .toc ul {\n  position: static !important;\n  display: block !important;\n  width: auto !important;\n  height: auto !important;\n  border-bottom: none !important;\n}\n\n.mwiki #toc ul,\n.mwiki .toc ul {\n  border-bottom: none !important;\n}\n\n/* Reset wrappers that might be using display: contents */\n.mwiki div[class*=\"toclimit-\"],\n.mwiki div.tocright {\n  display: block !important;\n  float: none !important;\n  clear: both !important;\n  width: 100% !important;\n}\n","article-style-st-babylon.css":"html {\n  background-color: white;\n}\n\nbody {\n  background: white;\n}\n\n.gdarticle {\n  background: white;\n}\n\nh3 {\n  font-size: 1em;\n}\n\n::selection {\n  background: #4492e8;\n  color: white;\n}\n\n/* Dictionary's name heading */\n.gddictname {\n  font-weight: normal;\n  font-size: 11px;\n  border: none;\n  border-top-left-radius: 8px;\n  border-top-right-radius: 0px;\n  background: #f0eded;\n  padding-top: 5px;\n  padding-bottom: 5px;\n}\n\n.gddicticon {\n  display: inline;\n  padding-right: 5px;\n}\n\n.gddicticon img {\n  border: 0;\n  height: 16px;\n  vertical-align: text-top;\n}\n\n/* The 'From ' string which precedes dictionary name in the heading */\n.gdfromprefix {\n  display: none;\n}\n\n/* Move the collapse/expand buttons to the right */\n.collapse_expand_area {\n  float: right;\n  margin-right: 2px;\n}\n\n.gdexpandicon,\n.gdexpandicon:hover,\n.gdcollapseicon,\n.gdcollapseicon:hover {\n  width: auto;\n  height: 100%;\n  vertical-align: text-bottom;\n}\n\n.gdexpandicon {\n  content: url(\"qrc:///icons/expand_article.svg\");\n}\n\n.gdexpandicon:hover {\n  content: url(\"qrc:///icons/expand_article_hovered.svg\");\n}\n\n.gdcollapseicon {\n  content: url(\"qrc:///icons/collapse_article.svg\");\n}\n\n.gdcollapseicon:hover {\n  content: url(\"qrc:///icons/collapse_article_hovered.svg\");\n}\n\n.bglpos {\n  color: black;\n  font-weight: bold;\n  font-size: 11px;\n  background: #f0eded;\n  display: inline;\n}\n\n.bgltrn {\n  color: #808080;\n  font-size: 12px;\n  display: inline;\n}\n\na,\n.mwiki a {\n  color: #0066cc;\n}\n","article-style-st-classic.css":"/******** Global, non-dictionary-specific classes ***********/\n\nhtml {\n  height: 100%;\n}\n\nbody {\n  background: #fefdeb;\n  font-family: Tahoma, Verdana, \"Lucida Sans Unicode\", sans-serif;\n  height: 100%;\n}\n\n/* This stylesheet is used to highligh current selection when doing a search.\n  It changes the default selection color (e.g. blue under Windows, orange under Ubuntu) */\n\n/* highlight/select color in Windows when a widget is inactive is nearly impossible to read (light gray).\n * then change it to green to use with the find option. */\n::selection {\n  background: #c00;\n  color: #fff;\n}\n\n/* Don't allow to select [] */\n:before,\n:after {\n  user-select: none;\n}\n\n/* Plaintext dictionaries are usually 80-column formatted and take a lot\n * of space. We try to use smaller fonts for them therefore. */\npre {\n  font-size: 12px;\n}\n\n/* Dictionary's name heading */\n.gddictname {\n  /* border: 1px dotted black;\n  padding: 0.2em;\n  padding-left: 0.5em;\n  margin-top: 1.2em;\n  margin-bottom: 9px;\n  font-weight: bold;\n  font-size: 14px;\n  background: #ffffdd; */\n}\n\n.gddicttitle {\n  user-select: none;\n}\n\n/* The 'From ' string which precedes dictionary name in the heading */\n.gdfromprefix {\n  display: none;\n}\n\n/* The article span. Here we have a padding/margin hack to make fragment links\n   behave better (have some space before the start of article) */\n.gdarticle {\n  display: block;\n  padding-top: 1px;\n  margin-top: -8px;\n  margin-bottom: 8px;\n  background: #fefdeb;\n  /*fix for invalid blg*/\n  font-style: normal;\n}\n\n/* CSS trick to prevent the floating elements to overflow\n   the article boundaries, see Issue #333. */\n.gdarticle:after {\n  content: \"\";\n  display: block;\n  height: 0;\n  clear: both;\n}\n\n/* Appears between the articles */\n.gdarticleseparator {\n  display: inline-block;\n  clear: both;\n}\n\n/* Dictionary query error description string */\n.gderrordesc {\n  font-style: italic;\n  background: url(\"qrc:///icons/warning.svg\") center left no-repeat !important;\n  background-size: auto min(100%, 24px);\n  padding-left: 2em !important;\n  margin: 1em;\n}\n\n/********* Babylon dictionaries' classes *********/\n\n/* Transcriptions in Babylon dictionaries */\n.bgltrn:before {\n  content: \"[\";\n}\n\n.bgltrn:after {\n  content: \"]\";\n}\n\n.bgltrn {\n  display: block;\n}\n\n/* Part of speech in Babylon dictionaries. Usually irrelevant,\n * therefore hidden */\n.bglpos {\n  display: none;\n}\n\n/* Right-to-left text */\n.bglrtl {\n  text-align: right;\n  direction: rtl;\n}\n\n/******** StarDict dictionaries' classes *********/\n\n/* StarDict type 'h' -- Html content. We don't normally do anything here. */\n.sdct_h {\n}\n\n.sdict_h_wav img {\n  vertical-align: middle;\n}\n\n/* StarDict type 'm' -- Pure meaning. Presented as <pre> */\n.sdct_m {\n}\n\n/* StarDict type 'l' -- Pure meaning which used to be in locale encoding. */\n.sdct_l {\n}\n\n/* StarDict type 'g' -- Pango Markup */\n.sdct_g {\n}\n\n/* StarDict type 't' -- Transcription */\n.sdct_t {\n  font-weight: bold;\n}\n\n/* StarDict type 'y' -- Chinese YinBiao or Japanese KANA */\n.sdct_y {\n}\n\n/* StarDict type 'x'. Should have xdxf_*-styled elements inside */\n.sdct_x {\n}\n\n/* Blockquotes in XDXF-styled elements are used\n   for indentation purposes, see Issue #305. */\n.sdct_x blockquote {\n  margin: 0px;\n  padding-left: 9px;\n  display: inline-block;\n}\n\n/******** XDXF markup classes *********/\n\ndiv.xdxf {\n}\n\n/* Key -- keys shouldn't normally be present in the article's body since they\n * are accounted for separately, hence we hide them */\n.xdxf_k {\n  display: none;\n}\n\n/* ...and if there's a break after it, we hide it too so we don't have an\n * extra vertical spacing. */\n.xdxf_k + br {\n  display: none;\n}\n\n/* Article structure tag */\n.xdxf_num {\n  color: red;\n  font-weight: bold;\n  padding-left: -15px;\n}\n.xdxf_def {\n  display: block;\n  border-color: #e3e3e3;\n  border-width: 1px;\n  border-style: dashed;\n  margin: 1px;\n  margin-left: 15px;\n}\n\n.xdxf_def:target {\n  /* this pseudoclass is used to marked out the referenced <def> that was just clicked */\n  border-color: red;\n  border-width: 1px;\n  border-style: double;\n}\n\n/* Abbreviation */\n.xdxf_abbr {\n  font-style: italic;\n  color: seagreen;\n  cursor: default;\n  border-bottom: 1px seagreen dotted;\n}\n\n/* Editorial comment */\n.xdxf_co,\n.xdxf_co_old {\n  color: darkslateblue;\n  font-style: italic;\n}\n.xdxf_co:before {\n  content: \"(\";\n}\n.xdxf_co:after {\n  content: \")\";\n}\n\n/* Grammar information */\n.xdxf_gr {\n  color: orangered;\n  display: block;\n}\n\n.xdxf_gr_old {\n  color: blue; /*orangered;*/\n}\n\n/* Example */\n.xdxf_ex {\n  color: #808080;\n  display: block;\n  margin-left: 14px;\n}\n\n.xdxf_ex_old {\n  color: #808080;\n}\n\n.xdxf_ex_source:before {\n  content: \"[\";\n}\n.xdxf_ex_source:after {\n  content: \"]\";\n}\n\n.xdxf_ex_tran:before {\n  content: \"— \";\n}\n\n.xdxf_ex_tran {\n  font-style: italic;\n}\n\n/* Direct translation */\n.xdxf_dtrn {\n  font-weight: bold;\n  color: #dd7800;\n}\n\n/* Transcription */\n.xdxf_tr:before {\n  content: \"[\";\n}\n\n.xdxf_tr:after {\n  content: \"]\";\n}\n\n.xdxf_tr,\n.xdxf_tr_old {\n  font-weight: bold;\n}\n\n/* Resource reference -- for now just a span. Since there's not yet a mechanism\n * to load resources off XDXF articles in GoldenDict, we just hide them. */\n.xdxf_rref {\n  display: none;\n}\n\n.xdxf_headwords {\n  font-size: 116%;\n  font-weight: bold;\n  margin-top: 10px;\n  margin-bottom: 10px;\n}\n\n/* The words in examples that are meaked out; they are marked out only when placed into <ex> tag */\n.xdxf_ex .xdxf_ex_markd,\n.xdxf_ex_old .xdxf_ex_markd {\n  color: black;\n  background-color: lightgray;\n}\n\n.xdxf_opt {\n  color: #808080;\n}\n\n/******** SDictionary markup classes *********/\n\n.sdict_forms {\n  font-style: italic;\n}\n\n/* Transcription */\n.sdict_tr:before {\n  content: \"[\";\n}\n\n.sdict_tr:after {\n  content: \"] \";\n}\n\n.sdict_tr {\n  font-weight: bold;\n}\n\n/************* LSA audio archives **************/\n\n/************* DSL dictionaries **************/\n\n.dsl_u {\n  text-decoration: underline;\n}\n\n.dsl_article {\n  display: inline;\n}\n\n.dsl_article .c_default_color {\n  color: green;\n}\n\n.dsl_m,\n.dsl_m0 {\n  padding-left: 0px;\n}\n\n.dsl_m1 {\n  padding-left: 9px;\n}\n\n.dsl_m2 {\n  padding-left: 18px;\n}\n\n.dsl_m3 {\n  padding-left: 27px;\n}\n\n.dsl_m4 {\n  padding-left: 36px;\n}\n\n.dsl_m5 {\n  padding-left: 45px;\n}\n\n.dsl_m6 {\n  padding-left: 54px;\n}\n\n.dsl_m7 {\n  padding-left: 63px;\n}\n\n.dsl_m8 {\n  padding-left: 72px;\n}\n\n.dsl_m9 {\n  padding-left: 81px;\n}\n\n.dsl_p, .dsl_p :not(a) /* DSL Feature: Enforce the style even if the children tags say otherwise, except links */ {\n  color: green !important; /* DSL label color must have highest priority */\n  font-style: italic;\n  cursor: default;\n  font-weight: normal; /* DSL feature: labels are always of normal weight */\n}\n\n.dsl_stress_without_accent {\n  display: none;\n}\n\n.dsl_t {\n  font-weight: bold;\n}\n\n.dsl_headwords {\n  font-weight: bold;\n  margin-top: 15px;\n  margin-bottom: 10px;\n}\n\n.dsl_headwords p {\n  font-weight: bold;\n  font-size: 15px;\n  margin: 0;\n}\n\n.dsl_definition p {\n  margin: 0;\n}\n\n.dsl_opt {\n  display: none;\n}\n\n.dsl_opt,\n.dsl_opt .dsl_ex,\n.dsl_opt .dsl_ex :not(a),\n.dsl_opt .dsl_ex [color] /* DSL Feature: Enforce the optional zone color even if the children tags say otherwise */ {\n  color: gray;\n}\n\n.dsl_ex,\n.dsl_ex .dsl_opt {\n  color: gray;\n}\n\n/* Style for expand optional parts button */\n.hidden_expand_opt {\n  color: blue;\n  cursor: pointer;\n  vertical-align: text-bottom;\n  width: 16px;\n  height: auto;\n}\n\n.dsl_s_wav img {\n  vertical-align: middle;\n}\n\n.dsl_video .img {\n  display: inline-block;\n  background: url(\"qrc:///icons/video.svg\");\n  background-repeat: no-repeat;\n  vertical-align: middle;\n  width: 22px;\n  height: 22px;\n  margin: 0;\n  padding: 0;\n}\n\n.dsl_video .filename {\n  display: none; /* by default, the file name is hidden */\n  padding-left: 5px;\n}\n\n/************* MDict dictionaries **************/\n.mdict {\n}\n\n.mdict a[name] {\n  text-decoration: none;\n  color: inherit;\n}\n\n/************* Zim dictionaries **************/\n\n.zimdict {\n  font-size: 110% !important;\n}\n\n.zimdict_headword {\n  font-weight: bold !important;\n}\n\n/************* Spelling suggestions *****************/\n\n.gdspellsuggestion {\n  /* Add some vertical space before the article */\n  margin-top: 1em;\n}\n\n/************* Stemmed suggestions *****************/\n\n.gdstemmedsuggestion {\n  /* Add some horizontal and vertical space */\n  margin-top: 1em;\n  margin-left: 1px;\n}\n\n.gdstemmedsuggestion_head {\n  margin-left: 11px;\n  font-style: italic;\n}\n\n.gdstemmedsuggestion_body {\n}\n\n/************* Dictd articles *****************/\n.dictd_article {\n  /* Add some vertical space before the article */\n  margin-top: 1em;\n}\n\n.dictd_phonetic:before,\n.dictd_phonetic:after {\n  content: \"\\\\\";\n  font-style: normal;\n}\n\n.dictd_phonetic:after {\n  margin-left: 3px;\n}\n\n.dictd_phonetic {\n  font-style: italic;\n  color: #009900;\n}\n\n.dictd_article a:link {\n  color: #0000ff;\n}\n\n.dictserver_from {\n  font-size: 110%;\n  font-weight: 600;\n}\n\n/************* Epwing dictionaries *****************/\n\n.epwing_narrow_font {\n  width: 0.5em;\n  height: 1em;\n  vertical-align: -15%;\n}\n\n.epwing_wide_font {\n  width: 1em;\n  height: 1em;\n  vertical-align: -15%;\n}\n\n.epwing_article {\n  display: inline;\n}\n\n/************* Websites *****************/\n\n.website_padding {\n  height: 1em;\n  clear: both;\n}\n\n/************* Forvo **************/\n\n.forvo_headword {\n  margin-top: 15px;\n  margin-bottom: 10px;\n  font-weight: bold;\n  font-size: 15px;\n}\n\n/* A table which contains a play icon and information about the sound */\n.forvo_play {\n  margin-top: 8px;\n  margin-left: 8px;\n}\n\n.forvo_user {\n  text-decoration: none;\n  color: green;\n}\n\n.forvo_location {\n  color: grey;\n}\n\n.forvo_positive_votes {\n  font-weight: bold;\n  color: green;\n}\n\n.forvo_negative_votes {\n  font-weight: bold;\n  color: red;\n}\n\n/************* MediaWiki articles *****************\n The following consist of excerpts from different .css files edited\n with a .mwiki prepended to each record.\n*/\n\n.mwiki {\n  /* Add some vertical space before the article */\n  margin-top: 1em;\n}\n\n.mwiki .topicon {\n  /* Those are padlocks on top and such -- we disable those for GoldenDict\n     since they look really ugly here */\n  display: none;\n}\n\n/************ common.css **************/\n\n/**\n * CSS in this file is used by *all* skins (that have any CSS at all).  Be\n * careful what you put in here, since what looks good in one skin may not in\n * another, but don't ignore the poor non-Monobook users either.\n */\n.mwiki .mw-plusminus-null {\n  color: #aaa;\n}\n\n.mwiki .texvc {\n  direction: ltr;\n  unicode-bidi: embed;\n}\n.mwiki img.tex {\n  vertical-align: middle;\n}\n.mwiki span.texhtml {\n  font-family: serif;\n}\n\n/* add a bit of margin space between the preview and the toolbar */\n/* this replaces the ugly <p><br /></p> we used to insert into the page source */\n.mwiki #wikiPreview.ontop {\n  margin-bottom: 1em;\n}\n\n/* Stop floats from intruding into edit area in previews */\n.mwiki #toolbar,\n.mwiki #wpTextbox1 {\n  clear: both;\n}\n\n.mwiki div#mw-js-message {\n  margin: 1em 5%;\n  padding: 0.5em 2.5%;\n  border: solid 1px #ddd;\n  background-color: #fcfcfc;\n}\n\n/* Edit section links */\n.mwiki .editsection {\n  float: right;\n  margin-left: 5px;\n}\n\n/**\n * File histories\n */\n.mwiki table.filehistory {\n  border: 1px solid #ccc;\n  border-collapse: collapse;\n}\n\n.mwiki table.filehistory th,\n.mwiki table.filehistory td {\n  padding: 0 0.2em 0 0.2em;\n  vertical-align: top;\n  border: 1px solid #ccc;\n}\n.mwiki table.filehistory th {\n  text-align: left;\n}\n.mwiki table.filehistory td.mw-imagepage-filesize,\n.mwiki table.filehistory th.mw-imagepage-filesize {\n  white-space: nowrap;\n}\n\n.mwiki table.filehistory td.filehistory-selected {\n  font-weight: bold;\n}\n\n/*\n * rev_deleted stuff\n */\n.mwiki li span.deleted,\n.mwiki span.history-deleted {\n  text-decoration: line-through;\n  color: #888;\n  font-style: italic;\n}\n\n.mwiki td.mw-label {\n  vertical-align: top;\n}\n.mwiki td.mw-submit {\n  white-space: nowrap;\n}\n/**\n * Forms\n */\n.mwiki body.ltr td.mw-label {\n  text-align: right;\n}\n.mwiki body.ltr td.mw-input {\n  text-align: left;\n}\n.mwiki body.ltr td.mw-submit {\n  text-align: left;\n}\n.mwiki body.rtl td.mw-label {\n  text-align: left;\n}\n.mwiki body.rtl td.mw-input {\n  text-align: right;\n}\n.mwiki body.rtl td.mw-submit {\n  text-align: right;\n}\n\n/**\n * Image captions\n */\n.mwiki body.rtl .thumbcaption {\n  text-align: right;\n}\n.mwiki body.rtl .magnify {\n  float: left;\n}\n\n.mwiki body.ltr .thumbcaption {\n  text-align: left;\n}\n.mwiki body.ltr .magnify {\n  float: right;\n}\n\n/**\n * Hidden categories\n */\n.mwiki .mw-hidden-cats-hidden {\n  display: none;\n}\n.mwiki .catlinks-allhidden {\n  display: none;\n}\n\n/* Convenience links to edit block, delete and protect reasons */\n.mwiki p.mw-ipb-conveniencelinks,\n.mwiki p.mw-protect-editreasons,\n.mwiki p.mw-filedelete-editreasons,\n.mwiki p.mw-delete-editreasons {\n  font-size: 90%;\n  float: right;\n}\n\n/* Search results */\n.mwiki div.searchresult {\n  font-size: 95%;\n  width: 38em;\n}\n.mwiki .mw-search-results li {\n  padding-bottom: 1em;\n  list-style: none;\n}\n.mwiki .mw-search-result-data {\n  color: green;\n  font-size: 97%;\n}\n\n.mwiki td#mw-search-menu {\n  padding-left: 6em;\n  font-size: 85%;\n}\n\n.mwiki div#mw-search-interwiki {\n  float: right;\n  width: 18em;\n  border-style: solid;\n  border-color: #aaaaaa;\n  border-width: 1px;\n  margin-top: 2ex;\n}\n\n.mwiki div#mw-search-interwiki li {\n  font-size: 95%;\n}\n\n.mwiki .mw-search-interwiki-more {\n  float: right;\n  font-size: 90%;\n}\n\n.mwiki span.searchalttitle {\n  font-size: 95%;\n}\n\n.mwiki div.searchdidyoumean {\n  font-size: 127%;\n  margin-bottom: 1ex;\n  margin-top: 1ex;\n  /* Note that this color won't affect the link, as desired. */\n  color: #c00;\n}\n\n.mwiki div.searchdidyoumean em {\n  font-weight: bold;\n}\n\n.mwiki .searchmatch {\n  font-weight: bold;\n}\n\n.mwiki div.searchresults {\n  border: 1px solid darkblue;\n  padding-top: 10px;\n  padding-bottom: 10px;\n  padding-left: 20px;\n  padding-right: 20px;\n}\n\n/*\n * UserRights stuff\n */\n.mwiki .mw-userrights-disabled {\n  color: #888;\n}\n\n.mwiki table.mw-userrights-groups * td,\n.mwiki table.mw-userrights-groups * th {\n  padding-right: 1.5em;\n}\n\n/*\n * OpenSearch ajax suggestions\n */\n.mwiki .os-suggest {\n  overflow: auto;\n  overflow-x: hidden;\n  position: absolute;\n  top: 0px;\n  left: 0px;\n  width: 0px;\n  background-color: white;\n  border-style: solid;\n  border-color: #aaaaaa;\n  border-width: 1px;\n  z-index: 99;\n  visibility: hidden;\n  font-size: 95%;\n}\n\n.mwiki table.os-suggest-results {\n  font-size: 95%;\n  cursor: pointer;\n  border: 0;\n  border-collapse: collapse;\n  width: 100%;\n}\n\n.mwiki td.os-suggest-result,\n.mwiki td.os-suggest-result-hl {\n  white-space: nowrap;\n  background-color: white;\n  color: black;\n  padding: 2px;\n}\n.mwiki td.os-suggest-result-hl,\n.mwiki td.os-suggest-result-hl-webkit {\n  background-color: #4c59a6;\n  color: white;\n}\n\n.mwiki .os-suggest-toggle {\n  position: relative;\n  left: 1ex;\n  font-size: 65%;\n}\n.mwiki .os-suggest-toggle-def {\n  position: absolute;\n  top: 0px;\n  left: 0px;\n  font-size: 65%;\n  visibility: hidden;\n}\n\n/* Page history styling */\n/* the auto-generated edit comments */\n.mwiki .autocomment {\n  color: gray;\n}\n.mwiki #pagehistory .history-user {\n  margin-left: 0.4em;\n  margin-right: 0.2em;\n}\n.mwiki #pagehistory span.minor {\n  font-weight: bold;\n}\n.mwiki #pagehistory li {\n  border: 1px solid white;\n}\n.mwiki #pagehistory li.selected {\n  background-color: #f9f9f9;\n  border: 1px dashed #aaa;\n}\n\n/*\n * Special:ListGroupRights styling\n * Special:Statistics styling\n*/\n\n.mwiki table.mw-listgrouprights-table,\n.mwiki table.mw-statistics-table {\n  border: 1px solid #ccc;\n  border-collapse: collapse;\n}\n\n.mwiki table.mw-listgrouprights-table tr {\n  vertical-align: top;\n}\n\n.mwiki table.mw-listgrouprights-table td,\n.mwiki table.mw-listgrouprights-table th,\n.mwiki table.mw-statistics-table td,\n.mwiki table.mw-statistics-table th {\n  padding: 0.5em 0.2em 0.5em 0.2em;\n  border: 1px solid #ccc;\n}\n\n.mwiki td.mw-statistics-numbers {\n  text-align: right;\n}\n\n/* Special:SpecialPages styling */\n.mwiki h4.mw-specialpagesgroup {\n  background-color: #dcdcdc;\n  padding: 2px;\n  margin: 0.3em 0em 0em 0em;\n}\n.mwiki .mw-specialpagerestricted {\n  font-weight: bold;\n}\n\n.mwiki #shared-image-dup,\n.mwiki #shared-image-conflict {\n  font-style: italic;\n}\n\n/* Special:EmailUser styling */\n.mwiki table.mw-emailuser-table {\n  width: 98%;\n}\n.mwiki td#mw-emailuser-sender,\n.mwiki td#mw-emailuser-recipient {\n  font-weight: bold;\n}\n\n/* Special:Prefixindex styling */\n.mwiki table#mw-prefixindex-list-table,\n.mwiki table#mw-prefixindex-nav-table {\n  width: 98%;\n  background-color: transparent;\n}\n.mwiki td#mw-prefixindex-nav-form {\n  font-size: smaller;\n  margin-bottom: 1em;\n  text-align: right;\n  vertical-align: top;\n}\n\n/*\n * Recreating deleted page warning\n * Reupload file warning\n * Page protection warning\n * incl. log entries for these warnings\n */\n.mwiki div.mw-warning-with-logexcerpt {\n  padding: 3px;\n  margin-bottom: 3px;\n  border: 2px solid #2f6fab;\n}\n.mwiki div.mw-warning-with-logexcerpt ul li {\n  font-size: 90%;\n}\n\n/* (show/hide) revision deletion links */\n.mwiki span.mw-revdelundel-link,\n.mwiki strong.mw-revdelundel-link {\n  font-family: monospace;\n  font-size: smaller;\n}\n\n/* feed links */\n.mwiki a.feedlink {\n  background: url(\"images/feed-icon.png\") center left no-repeat;\n  padding-left: 16px;\n}\n\n/************ monobook/main.css **************/\n\n/*\n** MediaWiki 'monobook' style sheet for CSS2-capable browsers.\n** Copyright Gabriel Wicke - http://wikidev.net/\n** License: GPL (http://www.gnu.org/copyleft/gpl.html)\n**\n** Loosely based on http://www.positioniseverything.net/ordered-floats.html by Big John\n** and the Plone 2.0 styles, see http://plone.org/ (Alexander Limi,Joe Geldart & Tom Croucher,\n** Michael Zeltner and Geir Bækholt)\n** All you guys rock :)\n*/\n\n.mwiki #column-content {\n  width: 100%;\n  float: right;\n  margin: 0 0 0.6em -12.2em;\n  padding: 0;\n}\n.mwiki #content {\n  margin: 2.8em 0 0 12.2em;\n  padding: 0 1em 1em 1em;\n  position: relative;\n  z-index: 2;\n}\n.mwiki #column-one {\n  padding-top: 160px;\n}\n.mwiki #content {\n  background: white;\n  color: black;\n  border: 1px solid #aaa;\n  border-right: none;\n  line-height: 1.5em;\n}\n/* the left column width is specified in class .portlet */\n\n/* scale back up to a sane default */\n.mwiki #globalWrapper {\n  font-size: 127%;\n  width: 100%;\n  margin: 0;\n  padding: 0;\n}\n.mwiki .visualClear {\n  clear: both;\n}\n\n/* general styles */\n\n.mwiki table {\n  font-size: 100%;\n  color: black;\n  /* we don't want the bottom borders of <h2>s to be visible through\n\t   floated tables */\n  background-color: white;\n}\n.mwiki fieldset table {\n  /* but keep table layouts in forms clean... */\n  background: none;\n}\n.mwiki a {\n  text-decoration: none;\n  color: #002bb8;\n  background: none;\n}\n.mwiki a:visited {\n  color: #5a3696;\n}\n.mwiki a:active {\n  color: #faa700;\n}\n.mwiki a:hover {\n  text-decoration: underline;\n}\n.mwiki a.stub {\n  color: #772233;\n}\n.mwiki a.new,\n.mwiki #p-personal a.new {\n  color: #ba0000;\n}\n.mwiki a.new:visited,\n.mwiki #p-personal a.new:visited {\n  color: #a55858;\n}\n\n.mwiki img {\n  border: none;\n  vertical-align: middle;\n}\n.mwiki p {\n  margin: 0.4em 0 0.5em 0;\n  line-height: 1.5em;\n}\n.mwiki p img {\n  margin: 0;\n}\n\n.mwiki hr {\n  height: 1px;\n  color: #aaa;\n  background-color: #aaa;\n  border: 0;\n  margin: 0.2em 0 0.2em 0;\n}\n\n.mwiki h1,\n.mwiki h2,\n.mwiki h3,\n.mwiki h4,\n.mwiki h5,\n.mwiki h6 {\n  color: black;\n  background: none;\n  font-weight: normal;\n  margin: 0;\n  padding-top: 0.5em;\n  padding-bottom: 0.17em;\n  border-bottom: 1px solid #aaa;\n}\n.mwiki h1 {\n  font-size: 188%;\n}\n.mwiki h1 .editsection {\n  font-size: 53%;\n}\n.mwiki h2 {\n  font-size: 150%;\n}\n.mwiki h2 .editsection {\n  font-size: 67%;\n}\n.mwiki h3,\n.mwiki h4,\n.mwiki h5,\n.mwiki h6 {\n  border-bottom: none;\n  font-weight: bold;\n}\n.mwiki h3 {\n  font-size: 132%;\n}\n.mwiki h3 .editsection {\n  font-size: 76%;\n  font-weight: normal;\n}\n.mwiki h4 {\n  font-size: 116%;\n}\n.mwiki h4 .editsection {\n  font-size: 86%;\n  font-weight: normal;\n}\n.mwiki h5 {\n  font-size: 100%;\n}\n.mwiki h5 .editsection {\n  font-weight: normal;\n}\n.mwiki h6 {\n  font-size: 80%;\n}\n.mwiki h6 .editsection {\n  font-size: 125%;\n  font-weight: normal;\n}\n\n.mwiki ul {\n  line-height: 1.5em;\n  list-style-type: square;\n  margin: 0.3em 0 0 1.5em;\n  padding: 0;\n}\n.mwiki ol {\n  line-height: 1.5em;\n  margin: 0.3em 0 0 3.2em;\n  padding: 0;\n  list-style-image: none;\n}\n.mwiki li {\n  margin-bottom: 0.1em;\n}\n.mwiki dt {\n  font-weight: bold;\n  margin-bottom: 0.1em;\n}\n.mwiki dl {\n  margin-top: 0.2em;\n  margin-bottom: 0.5em;\n}\n.mwiki dd {\n  line-height: 1.5em;\n  margin-left: 2em;\n  margin-bottom: 0.1em;\n}\n\n.mwiki fieldset {\n  border: 1px solid #2f6fab;\n  margin: 1em 0 1em 0;\n  padding: 0 1em 1em;\n  line-height: 1.5em;\n}\n.mwiki fieldset.nested {\n  margin: 0 0 0.5em 0;\n  padding: 0 0.5em 0.5em;\n}\n.mwiki legend {\n  padding: 0.5em;\n  font-size: 95%;\n}\n.mwiki form {\n  border: none;\n  margin: 0;\n}\n\n.mwiki textarea {\n  width: 100%;\n  padding: 0.1em;\n}\n\n.mwiki input.historysubmit {\n  padding: 0 0.3em 0.3em 0.3em !important;\n  font-size: 94%;\n  cursor: pointer;\n  height: 1.7em !important;\n  margin-left: 1.6em;\n}\n.mwiki select {\n  vertical-align: top;\n}\n.mwiki abbr,\n.mwiki .explain {\n  border-bottom: 1px dotted black;\n  color: black;\n  background: none;\n  cursor: help;\n}\n.mwiki q {\n  font-family: Times, \"Times New Roman\", serif;\n  font-style: italic;\n}\n/* disabled for now\n.mwiki blockquote {\n\tfont-family: Times, \"Times New Roman\", serif;\n\tfont-style: italic;\n}*/\n.mwiki code {\n  background-color: #f9f9f9;\n}\n.mwiki pre {\n  padding: 1em;\n  border: 1px dashed #2f6fab;\n  color: black;\n  background-color: #f9f9f9;\n  line-height: 1.1em;\n}\n\n/*\n** the main content area\n*/\n\n.mwiki #siteSub {\n  display: none;\n}\n.mwiki #jump-to-nav {\n  display: none;\n}\n\n.mwiki #contentSub,\n.mwiki #contentSub2 {\n  font-size: 84%;\n  line-height: 1.2em;\n  margin: 0 0 1.4em 1em;\n  color: #7d7d7d;\n  width: auto;\n}\n.mwiki span.subpages {\n  display: block;\n}\n\n/* Some space under the headers in the content area */\n.mwiki #bodyContent h1,\n.mwiki #bodyContent h2 {\n  margin-bottom: 0.6em;\n}\n.mwiki #bodyContent h3,\n.mwiki #bodyContent h4,\n.mwiki #bodyContent h5 {\n  margin-bottom: 0.3em;\n}\n.mwiki #firstHeading {\n  margin-bottom: 0.1em;\n  /* These two rules hack around bug 2013 (fix for more limited bug 11325).\n\t   When bug 2013 is fixed properly, they should be removed. */\n  line-height: 1.2em;\n  padding-bottom: 0;\n}\n\n/* user notification thing */\n.mwiki .usermessage {\n  background-color: #ffce7b;\n  border: 1px solid #ffa500;\n  color: black;\n  font-weight: bold;\n  margin: 2em 0 1em;\n  padding: 0.5em 1em;\n  vertical-align: middle;\n}\n.mwiki #siteNotice {\n  text-align: center;\n  font-size: 95%;\n  padding: 0 0.9em;\n}\n.mwiki #siteNotice p {\n  margin: 0;\n  padding: 0;\n}\n.mwiki .success {\n  color: green;\n  font-size: larger;\n}\n.mwiki .error {\n  color: red;\n  font-size: larger;\n}\n.mwiki .errorbox,\n.mwiki .successbox {\n  font-size: larger;\n  border: 2px solid;\n  padding: 0.5em 1em;\n  float: left;\n  margin-bottom: 2em;\n  color: #000;\n}\n.mwiki .errorbox {\n  border-color: red;\n  background-color: #fff2f2;\n}\n.mwiki .successbox {\n  border-color: green;\n  background-color: #dfd;\n}\n.mwiki .errorbox h2,\n.mwiki .successbox h2 {\n  font-size: 1em;\n  font-weight: bold;\n  display: inline;\n  margin: 0 0.5em 0 0;\n  border: none;\n}\n\n.mwiki .catlinks {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  margin-top: 1em;\n  clear: both;\n}\n/* currently unused, intended to be used by a metadata box\nin the bottom-right corner of the content area */\n.mwiki .documentDescription {\n  /* The summary text describing the document */\n  font-weight: bold;\n  display: block;\n  margin: 1em 0;\n  line-height: 1.5em;\n}\n.mwiki .documentByLine {\n  text-align: right;\n  font-size: 90%;\n  clear: both;\n  font-weight: normal;\n  color: #76797c;\n}\n\n/* emulate center */\n.mwiki .center {\n  width: 100%;\n  text-align: center;\n}\n.mwiki *.center * {\n  margin-left: auto;\n  margin-right: auto;\n}\n/* small for tables and similar */\n.mwiki .small,\n.mwiki .small * {\n  font-size: 94%;\n}\n.mwiki table.small {\n  font-size: 100%;\n}\n\n/*\n** content styles\n*/\n\n.mwiki #toc,\n.mwiki .toc,\n.mwiki .mw-warning {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  font-size: 95%;\n}\n.mwiki #toc h2,\n.mwiki .toc h2 {\n  display: inline;\n  border: none;\n  padding: 0;\n  font-size: 100%;\n  font-weight: bold;\n}\n.mwiki #toc #toctitle,\n.mwiki .toc #toctitle,\n.mwiki #toc .toctitle,\n.mwiki .toc .toctitle {\n  text-align: center;\n}\n.mwiki #toc ul,\n.mwiki .toc ul {\n  list-style-type: none;\n  list-style-image: none;\n  margin-left: 0;\n  padding-left: 0;\n  text-align: left;\n}\n.mwiki #toc ul ul,\n.mwiki .toc ul ul {\n  margin: 0 0 0 2em;\n}\n.mwiki #toc .toctoggle,\n.mwiki .toc .toctoggle {\n  font-size: 94%;\n}\n\n.mwiki .mw-warning {\n  margin-left: 50px;\n  margin-right: 50px;\n  text-align: center;\n}\n\n/* images */\n.mwiki div.floatright,\n.mwiki table.floatright {\n  clear: right;\n  float: right;\n  position: relative;\n  margin: 0 0 0.5em 0.5em;\n  border: 0;\n  /*\n\tborder: .5em solid white;\n\tborder-width: .5em 0 .8em 1.4em;\n*/\n}\n.mwiki div.floatright p {\n  font-style: italic;\n}\n.mwiki div.floatleft,\n.mwiki table.floatleft {\n  float: left;\n  clear: left;\n  position: relative;\n  margin: 0 0.5em 0.5em 0;\n  border: 0;\n  /*\n\tmargin: .3em .5em .5em 0;\n\tborder: .5em solid white;\n\tborder-width: .5em 1.4em .8em 0;\n*/\n}\n.mwiki div.floatleft p {\n  font-style: italic;\n}\n/* thumbnails */\n.mwiki div.thumb {\n  margin-bottom: 0.5em;\n  border-style: solid;\n  border-color: white;\n  width: auto;\n}\n.mwiki div.thumbinner {\n  border: 1px solid #ccc;\n  padding: 3px !important;\n  background-color: #f9f9f9;\n  font-size: 94%;\n  text-align: center;\n  overflow: hidden;\n}\n.mwiki html .thumbimage {\n  border: 1px solid #ccc;\n}\n.mwiki html .thumbcaption {\n  border: none;\n  text-align: left;\n  line-height: 1.4em;\n  padding: 3px !important;\n  font-size: 94%;\n}\n.mwiki div.magnify {\n  float: right;\n  border: none !important;\n  background: none !important;\n}\n.mwiki div.magnify a,\n.mwiki div.magnify img {\n  display: block;\n  border: none !important;\n  background: none !important;\n}\n.mwiki div.tright {\n  clear: right;\n  float: right;\n  border-width: 0.5em 0 0.8em 1.4em;\n}\n.mwiki div.tleft {\n  float: left;\n  clear: left;\n  margin-right: 0.5em;\n  border-width: 0.5em 1.4em 0.8em 0;\n}\n.mwiki img.thumbborder {\n  border: 1px solid #dddddd;\n}\n.mwiki .hiddenStructure {\n  display: none;\n}\n\n/*\n** classes for special content elements like town boxes\n** intended to be referenced directly from the wiki src\n*/\n\n/*\n** User styles\n*/\n/* table standards */\n.mwiki table.rimage {\n  float: right;\n  position: relative;\n  margin-left: 1em;\n  margin-bottom: 1em;\n  text-align: center;\n}\n.mwiki .toccolours {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  font-size: 95%;\n}\n\n/*\n** edit views etc\n*/\n.mwiki .special li {\n  line-height: 1.4em;\n  margin: 0;\n  padding: 0;\n}\n\n/*\n** keep the whitespace in front of the ^=, hides rule from konqueror\n** this is css3, the validator doesn't like it when validating as css2\n*/\n\n.mwiki #bodyContent a.external[href$=\".ogg\"],\n.mwiki #bodyContent a.external[href$=\".OGG\"],\n.mwiki #bodyContent a.external[href$=\".oga\"],\n.mwiki #bodyContent a.external[href$=\".OGA\"],\n.mwiki #bodyContent a.external[href$=\".mid\"],\n.mwiki #bodyContent a.external[href$=\".MID\"],\n.mwiki #bodyContent a.external[href$=\".midi\"],\n.mwiki #bodyContent a.external[href$=\".MIDI\"],\n.mwiki #bodyContent a.external[href$=\".mp3\"],\n.mwiki #bodyContent a.external[href$=\".MP3\"],\n.mwiki #bodyContent a.external[href$=\".wav\"],\n.mwiki #bodyContent a.external[href$=\".WAV\"],\n.mwiki #bodyContent a.external[href$=\".wma\"],\n.mwiki #bodyContent a.external[href$=\".WMA\"],\n.mwiki .link-audio {\n  background: url(\"qrc:///icons/audio.png\") center right no-repeat;\n  padding-right: 1em;\n}\n.mwiki #bodyContent a.external[href$=\".ogm\"],\n.mwiki #bodyContent a.external[href$=\".OGM\"],\n.mwiki #bodyContent a.external[href$=\".avi\"],\n.mwiki #bodyContent a.external[href$=\".AVI\"],\n.mwiki #bodyContent a.external[href$=\".mpeg\"],\n.mwiki #bodyContent a.external[href$=\".MPEG\"],\n.mwiki #bodyContent a.external[href$=\".mpg\"],\n.mwiki #bodyContent a.external[href$=\".MPG\"],\n.mwiki .link-video {\n  background: url(\"qrc:///icons/video.svg\") center right no-repeat;\n  padding-right: 1em;\n}\n.mwiki #bodyContent a.external[href$=\".pdf\"],\n.mwiki #bodyContent a.external[href$=\".PDF\"],\n.mwiki #bodyContent a.external[href*=\".pdf#\"],\n.mwiki #bodyContent a.external[href*=\".PDF#\"],\n.mwiki #bodyContent a.external[href*=\".pdf?\"],\n.mwiki #bodyContent a.external[href*=\".PDF?\"],\n.mwiki .link-document {\n  background: url(\"qrc:///icons/document.png\") center right no-repeat;\n  padding-right: 12px;\n}\n\n/* disable interwiki styling */\n.mwiki #bodyContent a.extiw,\n.mwiki #bodyContent a.extiw:active {\n  color: #36b;\n  background: none;\n  padding: 0;\n}\n.mwiki #bodyContent a.external {\n  color: #36b;\n}\n/* this can be used in the content area to switch off\nspecial external link styling */\n.mwiki #bodyContent .plainlinks a {\n  background: none !important;\n  padding: 0 !important;\n}\n/*\n** Structural Elements\n*/\n\n/*\n** general portlet styles (elements in the quickbar)\n*/\n.mwiki .portlet {\n  border: none;\n  margin: 0 0 0.5em;\n  padding: 0;\n  float: none;\n  width: 11.6em;\n  overflow: hidden;\n}\n.mwiki .portlet h4 {\n  font-size: 95%;\n  font-weight: normal;\n  white-space: nowrap;\n}\n.mwiki .portlet h5 {\n  background: transparent;\n  padding: 0 1em 0 0.5em;\n  display: inline;\n  height: 1em;\n  text-transform: lowercase;\n  font-size: 91%;\n  font-weight: normal;\n  white-space: nowrap;\n}\n.mwiki .portlet h6 {\n  background: #ffae2e;\n  border: 1px solid #2f6fab;\n  border-style: solid solid none solid;\n  padding: 0 1em 0 1em;\n  text-transform: lowercase;\n  display: block;\n  font-size: 1em;\n  height: 1.2em;\n  font-weight: normal;\n  white-space: nowrap;\n}\n.mwiki .pBody {\n  font-size: 95%;\n  background-color: white;\n  color: black;\n  border-collapse: collapse;\n  border: 1px solid #aaa;\n  padding: 0 0.8em 0.3em 0.5em;\n}\n.mwiki .portlet h1,\n.mwiki .portlet h2,\n.mwiki .portlet h3,\n.mwiki .portlet h4 {\n  margin: 0;\n  padding: 0;\n}\n.mwiki .portlet ul {\n  line-height: 1.5em;\n  list-style-type: square;\n  font-size: 95%;\n}\n.mwiki .portlet li {\n  padding: 0;\n  margin: 0;\n}\n\n/*\n** Logo properties\n*/\n\n.mwiki #p-logo {\n  top: 0;\n  left: 0;\n  position: absolute; /*needed to use z-index */\n  z-index: 3;\n  height: 155px;\n  width: 12em;\n  overflow: visible;\n}\n.mwiki #p-logo h5 {\n  display: none;\n}\n.mwiki #p-logo a,\n.mwiki #p-logo a:hover {\n  display: block;\n  height: 155px;\n  width: 12.2em;\n  background-repeat: no-repeat;\n  background-position: 35% 50% !important;\n  text-decoration: none;\n}\n\n/*\n** Search portlet\n*/\n.mwiki #p-search {\n  position: relative;\n  z-index: 3;\n}\n.mwiki input.searchButton {\n  margin-top: 1px;\n  font-size: 95%;\n}\n.mwiki #searchGoButton {\n  padding-left: 0.5em;\n  padding-right: 0.5em;\n  font-weight: bold;\n}\n.mwiki #searchInput {\n  width: 10.9em;\n  margin: 0;\n  font-size: 95%;\n}\n.mwiki #p-search .pBody {\n  padding: 0.5em 0.4em 0.4em 0.4em;\n  text-align: center;\n}\n.mwiki #p-search #searchform div div {\n  margin-top: 0.4em;\n  font-size: 95%;\n}\n/*\n** the personal toolbar\n*/\n.mwiki #p-personal {\n  position: absolute;\n  left: 0;\n  top: 0;\n  z-index: 0;\n}\n.mwiki #p-personal {\n  width: 100%;\n  white-space: nowrap;\n  padding: 0;\n  margin: 0;\n  border: none;\n  background: none;\n  overflow: visible;\n  line-height: 1.2em;\n}\n.mwiki #p-personal h5 {\n  display: none;\n}\n.mwiki #p-personal .portlet,\n.mwiki #p-personal .pBody {\n  z-index: 0;\n  padding: 0;\n  margin: 0;\n  border: none;\n  overflow: visible;\n  background: none;\n}\n/* this is the ul contained in the portlet */\n.mwiki #p-personal ul {\n  border: none;\n  line-height: 1.4em;\n  color: #2f6fab;\n  padding: 0 2em 0 3em;\n  margin: 0;\n  text-align: right;\n  list-style: none;\n  z-index: 0;\n  background: none;\n  cursor: default;\n}\n.mwiki #p-personal li {\n  z-index: 0;\n  border: none;\n  padding: 0;\n  display: inline;\n  color: #2f6fab;\n  margin-left: 1em;\n  line-height: 1.2em;\n  background: none;\n}\n.mwiki #p-personal li a {\n  text-decoration: none;\n  color: #005896;\n  padding-bottom: 0.2em;\n  background: none;\n}\n.mwiki #p-personal li a:hover {\n  background-color: white;\n  padding-bottom: 0.2em;\n  text-decoration: none;\n}\n.mwiki #p-personal li.active a:hover {\n  background-color: transparent;\n}\n/* the icon in front of the user name, single quotes\nin bg url to hide it from iemac */\n.mwiki li#pt-userpage,\n.mwiki li#pt-anonuserpage,\n.mwiki li#pt-login {\n  padding-left: 20px;\n  text-transform: none;\n}\n.mwiki #p-personal ul {\n  text-transform: lowercase;\n}\n.mwiki #p-personal li.active {\n  font-weight: bold;\n}\n/*\n** the page-related actions- page/talk, edit etc\n*/\n.mwiki #p-cactions {\n  position: absolute;\n  top: 1.3em;\n  left: 11.5em;\n  margin: 0;\n  white-space: nowrap;\n  width: 76%;\n  line-height: 1.1em;\n  overflow: visible;\n  background: none;\n  border-collapse: collapse;\n  padding-left: 1em;\n  list-style: none;\n  font-size: 95%;\n}\n.mwiki #p-cactions ul {\n  list-style: none;\n}\n.mwiki #p-cactions li {\n  display: inline;\n  border: 1px solid #aaa;\n  border-bottom: none;\n  padding: 0 0 0.1em 0;\n  margin: 0 0.3em 0 0;\n  overflow: visible;\n  background: white;\n}\n.mwiki #p-cactions li.selected {\n  border-color: #fabd23;\n  padding: 0 0 0.2em 0;\n  font-weight: bold;\n}\n.mwiki #p-cactions li a {\n  background-color: #fbfbfb;\n  color: #002bb8;\n  border: none;\n  padding: 0 0.8em 0.3em;\n  position: relative;\n  z-index: 0;\n  margin: 0;\n  text-decoration: none;\n}\n.mwiki #p-cactions li.selected a {\n  z-index: 3;\n  padding: 0 1em 0.2em !important;\n  background-color: white;\n}\n.mwiki #p-cactions .new a {\n  color: #ba0000;\n}\n.mwiki #p-cactions li a:hover {\n  z-index: 3;\n  text-decoration: none;\n  background-color: white;\n}\n.mwiki #p-cactions h5 {\n  display: none;\n}\n.mwiki #p-cactions li.istalk {\n  margin-right: 0;\n}\n.mwiki #p-cactions li.istalk a {\n  padding-right: 0.5em;\n}\n.mwiki #p-cactions #ca-addsection a {\n  padding-left: 0.4em;\n  padding-right: 0.4em;\n}\n/* offsets to distinguish the tab groups */\n.mwiki li#ca-talk {\n  margin-right: 1.6em;\n}\n.mwiki li#ca-watch,\n.mwiki li#ca-unwatch,\n.mwiki li#ca-varlang-0,\n.mwiki li#ca-print {\n  margin-left: 1.6em;\n}\n.mwiki #p-cactions .pBody {\n  font-size: 1em;\n  background-color: transparent;\n  color: inherit;\n  border-collapse: inherit;\n  border: 0;\n  padding: 0;\n}\n.mwiki #p-cactions .hiddenStructure {\n  display: none;\n}\n.mwiki #p-cactions li a {\n  text-transform: lowercase;\n}\n\n.mwiki #p-lang {\n  position: relative;\n  z-index: 3;\n}\n\n/* #t-iscite is only used by the Cite extension, come up with some\n * system which allows extensions to add to this file on the fly\n */\n.mwiki #t-ispermalink,\n.mwiki #t-iscite {\n  color: #999;\n}\n/*\n** footer\n*/\n.mwiki #footer {\n  background-color: white;\n  border-top: 1px solid #fabd23;\n  border-bottom: 1px solid #fabd23;\n  margin: 0.6em 0 1em 0;\n  padding: 0.4em 0 1.2em 0;\n  text-align: center;\n  font-size: 90%;\n}\n.mwiki #footer li {\n  display: inline;\n  margin: 0 1.3em;\n}\n.mwiki #f-poweredbyico,\n.mwiki #f-copyrightico {\n  margin: 0 8px;\n  position: relative;\n  top: -2px; /* Bump it up just a tad */\n}\n.mwiki #f-poweredbyico {\n  float: right;\n  height: 1%;\n}\n.mwiki #f-copyrightico {\n  float: left;\n  height: 1%;\n}\n\n/* js pref toc */\n.mwiki #preftoc {\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  clear: both;\n}\n.mwiki #preftoc li {\n  background-color: #f0f0f0;\n  color: #000;\n}\n.mwiki #preftoc li {\n  margin: 1px -2px 1px 2px;\n  float: left;\n  padding: 2px 0 3px 0;\n  border: 1px solid #fff;\n  border-right-color: #716f64;\n  border-bottom: 0;\n  position: relative;\n  white-space: nowrap;\n  list-style-type: none;\n  list-style-image: none;\n  z-index: 3;\n}\n.mwiki #preftoc li.selected {\n  font-weight: bold;\n  background-color: #f9f9f9;\n  border: 1px solid #aaa;\n  border-bottom: none;\n  cursor: default;\n  top: 1px;\n  padding-top: 2px;\n  margin-right: -3px;\n}\n.mwiki #preftoc > li.selected {\n  top: 2px;\n}\n.mwiki #preftoc a,\n.mwiki #preftoc a:active {\n  display: block;\n  color: #000;\n  padding: 0 0.7em;\n  position: relative;\n  text-decoration: none;\n}\n.mwiki #preftoc li.selected a {\n  cursor: default;\n  text-decoration: none;\n}\n.mwiki #prefcontrol {\n  padding-top: 2em;\n  clear: both;\n}\n.mwiki #preferences {\n  margin: 0;\n  border: 1px solid #aaa;\n  clear: both;\n  padding: 1.5em;\n  background-color: #f9f9f9;\n}\n.mwiki .prefsection {\n  border: none;\n  padding: 0;\n  margin: 0;\n}\n.mwiki .prefsection fieldset {\n  border: 1px solid #aaa;\n  float: left;\n  margin-right: 2em;\n}\n.mwiki .prefsection legend {\n  font-weight: bold;\n}\n.mwiki .prefsection table,\n.mwiki .prefsection legend {\n  background-color: #f9f9f9;\n}\n.mwiki .mainLegend {\n  display: none;\n}\n.mwiki div.prefsectiontip {\n  font-size: x-small;\n  padding: 0.2em 2em;\n  color: #666;\n}\n.mwiki .btnSavePrefs {\n  font-weight: bold;\n  padding-left: 0.3em;\n  padding-right: 0.3em;\n}\n\n.mwiki .preferences-login {\n  clear: both;\n  margin-bottom: 1.5em;\n}\n\n.mwiki .prefcache {\n  font-size: 90%;\n  margin-top: 2em;\n}\n\n.mwiki div#userloginForm form,\n.mwiki div#userlogin form#userlogin2 {\n  margin: 0 3em 1em 0;\n  border: 1px solid #aaa;\n  clear: both;\n  padding: 1.5em 2em;\n  background-color: #f9f9f9;\n  float: left;\n}\n.mwiki .rtl div#userloginForm form,\n.mwiki .rtl div#userlogin form#userlogin2 {\n  float: right;\n}\n\n.mwiki div#userloginForm table,\n.mwiki div#userlogin form#userlogin2 table {\n  background-color: #f9f9f9;\n}\n\n.mwiki div#userloginForm h2,\n.mwiki div#userlogin form#userlogin2 h2 {\n  padding-top: 0;\n}\n\n.mwiki div#userlogin .captcha,\n.mwiki div#userloginForm .captcha {\n  border: 1px solid #bbb;\n  padding: 1.5em 2em;\n  background-color: white;\n}\n\n.mwiki #loginend,\n.mwiki #signupend {\n  clear: both;\n}\n\n.mwiki #userloginprompt,\n.mwiki #languagelinks {\n  font-size: 85%;\n}\n\n.mwiki #login-sectiontip {\n  font-size: 85%;\n  line-height: 1.2;\n  padding-top: 2em;\n}\n\n.mwiki #userlogin .loginText,\n.mwiki #userlogin .loginPassword {\n  width: 12em;\n}\n\n.mwiki #userloginlink a,\n.mwiki #wpLoginattempt,\n.mwiki #wpCreateaccount {\n  font-weight: bold;\n}\n\n/* IE/Mac fixes were cut out */\n\n.mwiki .redirectText {\n  font-size: 150%;\n  margin: 5px;\n}\n\n.mwiki .printfooter {\n  display: none;\n}\n\n.mwiki .not-patrolled {\n  background-color: #ffa;\n}\n.mwiki div.patrollink {\n  clear: both;\n  font-size: 75%;\n  text-align: right;\n}\n.mwiki span.newpage,\n.mwiki span.minor,\n.mwiki span.bot {\n  font-weight: bold;\n}\n.mwiki span.unpatrolled {\n  font-weight: bold;\n  color: red;\n}\n\n.mwiki .sharedUploadNotice {\n  font-style: italic;\n}\n\n.mwiki span.updatedmarker {\n  color: black;\n  background-color: #0f0;\n}\n\n.mwiki table.gallery {\n  border: 1px solid #ccc;\n  margin: 2px;\n  padding: 2px;\n  background-color: white;\n}\n\n.mwiki table.gallery tr {\n  vertical-align: top;\n}\n\n.mwiki table.gallery td {\n  vertical-align: top;\n  background-color: #f9f9f9;\n  border: solid 2px white;\n}\n/* Keep this temporarily so that cached pages will display right */\n.mwiki table.gallery td.galleryheader {\n  text-align: center;\n  font-weight: bold;\n}\n.mwiki table.gallery caption {\n  font-weight: bold;\n}\n\n.mwiki div.gallerybox {\n  margin: 2px;\n}\n\n.mwiki div.gallerybox div.thumb {\n  text-align: center;\n  border: 1px solid #ccc;\n  margin: 2px;\n}\n\n.mwiki div.gallerytext {\n  overflow: hidden;\n  font-size: 94%;\n  padding: 2px 4px;\n}\n\n.mwiki span.comment {\n  font-style: italic;\n}\n\n.mwiki span.changedby {\n  font-size: 95%;\n}\n\n.mwiki .previewnote {\n  text-indent: 3em;\n  color: #c00;\n  border-bottom: 1px solid #aaa;\n  padding-bottom: 1em;\n  margin-bottom: 1em;\n}\n\n.mwiki .previewnote p {\n  margin: 0;\n  padding: 0;\n}\n\n.mwiki .editExternally {\n  border: 1px solid gray;\n  background-color: #ffffff;\n  padding: 3px;\n  margin-top: 0.5em;\n  float: left;\n  font-size: small;\n  text-align: center;\n}\n.mwiki .editExternallyHelp {\n  font-style: italic;\n  color: gray;\n}\n\n.mwiki .toggle {\n  margin-left: 2em;\n  text-indent: -2em;\n}\n\n/* Classes for EXIF data display */\n.mwiki table.mw_metadata {\n  font-size: 0.8em;\n  margin-left: 0.5em;\n  margin-bottom: 0.5em;\n  width: 300px;\n}\n\n.mwiki table.mw_metadata caption {\n  font-weight: bold;\n}\n\n.mwiki table.mw_metadata th {\n  font-weight: normal;\n}\n\n.mwiki table.mw_metadata td {\n  padding: 0.1em;\n}\n\n.mwiki table.mw_metadata {\n  border: none;\n  border-collapse: collapse;\n}\n\n.mwiki table.mw_metadata td,\n.mwiki table.mw_metadata th {\n  text-align: center;\n  border: 1px solid #aaaaaa;\n  padding-left: 0.1em;\n  padding-right: 0.1em;\n}\n\n.mwiki table.mw_metadata th {\n  background-color: #f9f9f9;\n}\n\n.mwiki table.mw_metadata td {\n  background-color: #fcfcfc;\n}\n\n.mwiki table.collapsed tr.collapsable {\n  display: none;\n}\n\n/* filetoc */\n.mwiki ul#filetoc {\n  text-align: center;\n  border: 1px solid #aaaaaa;\n  background-color: #f9f9f9;\n  padding: 5px;\n  font-size: 95%;\n  margin-bottom: 0.5em;\n  margin-left: 0;\n  margin-right: 0;\n}\n\n.mwiki #filetoc li {\n  display: inline;\n  list-style-type: none;\n  padding-right: 2em;\n}\n\n.mwiki input#wpSummary {\n  width: 80%;\n}\n\n/* @bug 1714 */\n.mwiki input#wpSave,\n.mwiki input#wpDiff {\n  margin-right: 0.33em;\n}\n\n.mwiki #wpSave {\n  font-weight: bold;\n}\n\n/* Classes for article validation */\n\n.mwiki table.revisionform_default {\n  border: 1px solid #000000;\n}\n\n.mwiki table.revisionform_focus {\n  border: 1px solid #000000;\n  background-color: #00bbff;\n}\n\n.mwiki tr.revision_tr_default {\n  background-color: #eeeeee;\n}\n\n.mwiki tr.revision_tr_first {\n  background-color: #dddddd;\n}\n\n.mwiki p.revision_saved {\n  color: green;\n  font-weight: bold;\n}\n\n.mwiki #mw_trackbacks {\n  border: solid 1px #bbbbff;\n  background-color: #eeeeff;\n  padding: 0.2em;\n}\n\n/* Allmessages table */\n\n.mwiki #allmessagestable th {\n  background-color: #b2b2ff;\n}\n\n.mwiki #allmessagestable tr.orig {\n  background-color: #ffe2e2;\n}\n\n.mwiki #allmessagestable tr.new {\n  background-color: #e2ffe2;\n}\n\n.mwiki #allmessagestable tr.def {\n  background-color: #f0f0ff;\n}\n\n/* noarticletext */\n.mwiki div.noarticletext {\n  border: 1px solid #ccc;\n  background: #fff;\n  padding: 0.2em 1em;\n  color: #000;\n}\n\n.mwiki div#searchTargetContainer {\n  left: 10px;\n  top: 10px;\n  width: 90%;\n  background: white;\n}\n\n.mwiki div#searchTarget {\n  padding: 3px;\n  margin: 5px;\n  background: #f0f0f0;\n  border: solid 1px blue;\n}\n\n.mwiki div#searchTarget ul li {\n  list-style: none;\n}\n\n.mwiki div#searchTarget ul li:before {\n  color: orange;\n  content: \"\\00BB \\0020\";\n}\n\n.mwiki div#searchTargetHide {\n  float: right;\n  border: solid 1px black;\n  background: #dcdcdc;\n  padding: 2px;\n}\n\n.mwiki #powersearch p {\n  margin-top: 0px;\n}\n\n.mwiki div.multipageimagenavbox {\n  border: solid 1px silver;\n  padding: 4px;\n  margin: 1em;\n  background: #f0f0f0;\n}\n\n.mwiki div.multipageimagenavbox div.thumb {\n  border: none;\n  margin-left: 2em;\n  margin-right: 2em;\n}\n\n.mwiki div.multipageimagenavbox hr {\n  margin: 6px;\n}\n\n.mwiki table.multipageimage td {\n  text-align: center;\n}\n\n/** Special:Version */\n\n.mwiki table#sv-ext,\ntable#sv-hooks,\n.mwiki table#sv-software {\n  margin: 1em;\n  padding: 0em;\n}\n\n.mwiki #sv-ext td,\n.mwiki #sv-hooks td,\n.mwiki #sv-software td,\n.mwiki #sv-ext th,\n.mwiki #sv-hooks th,\n.mwiki #sv-software th {\n  border: 1px solid #a0a0a0;\n  padding: 0 0.15em 0 0.15em;\n}\n.mwiki #sv-ext th,\n.mwiki #sv-hooks th,\n.mwiki #sv-software th {\n  background-color: #f0f0f0;\n  color: black;\n  padding: 0 0.15em 0 0.15em;\n}\n.mwiki tr.sv-space {\n  height: 0.8em;\n  border: none;\n}\n.mwiki tr.sv-space td {\n  display: none;\n}\n\n/*\n  Table pager (e.g. Special:Imagelist)\n  - remove underlines from the navigation link\n  - collapse borders\n  - set the borders to outsets (similar to Special:Allmessages)\n  - remove line wrapping for all td and th, set background color\n  - restore line wrapping for the last two table cells (description and size)\n*/\n.mwiki .TablePager {\n  min-width: 80%;\n}\n.mwiki .TablePager_nav a {\n  text-decoration: none;\n}\n.mwiki .TablePager {\n  border-collapse: collapse;\n}\n.mwiki .TablePager,\n.mwiki .TablePager td,\n.mwiki .TablePager th {\n  border: 1px solid #aaaaaa;\n  padding: 0 0.15em 0 0.15em;\n}\n.mwiki .TablePager th {\n  background-color: #eeeeff;\n}\n.mwiki .TablePager td {\n  background-color: #ffffff;\n}\n.mwiki .TablePager tr:hover td {\n  background-color: #eeeeff;\n}\n\n.mwiki .imagelist td,\n.mwiki .imagelist th {\n  white-space: nowrap;\n}\n.mwiki .imagelist .TablePager_col_links {\n  background-color: #eeeeff;\n}\n.mwiki .imagelist .TablePager_col_img_description {\n  white-space: normal;\n}\n.mwiki .imagelist th.TablePager_sort {\n  background-color: #ccccff;\n}\n\n.mwiki .templatesUsed {\n  margin-top: 1.5em;\n}\n\n.mwiki .mw-summary-preview {\n  margin: 0.1em 0;\n}\n\n/* Friendlier slave lag warnings */\n.mwiki div.mw-lag-warn-normal,\n.mwiki div.mw-lag-warn-high {\n  padding: 3px;\n  text-align: center;\n  margin: 3px auto;\n}\n.mwiki div.mw-lag-warn-normal {\n  border: 1px solid #ffcc66;\n  background-color: #ffffcc;\n}\n.mwiki div.mw-lag-warn-high {\n  font-weight: bold;\n  border: 2px solid #ff0033;\n  background-color: #ffcccc;\n}\n\n.mwiki .MediaTransformError {\n  background-color: #ccc;\n  padding: 0.1em;\n}\n.mwiki .MediaTransformError td {\n  text-align: center;\n  vertical-align: middle;\n  font-size: 90%;\n}\n\n/** Special:Search stuff */\n.mwiki div#mw-search-interwiki-caption {\n  text-align: center;\n  font-weight: bold;\n  font-size: 95%;\n}\n\n.mwiki .mw-search-interwiki-project {\n  font-size: 97%;\n  text-align: left;\n  padding-left: 0.2em;\n  padding-right: 0.15em;\n  padding-bottom: 0.2em;\n  padding-top: 0.15em;\n  background: #cae8ff;\n}\n\n/* God-damned hack for the crappy layout */\n.mwiki .os-suggest {\n  font-size: 127%;\n}\n\n/**** Excerpts from http://en.wikipedia.org/wiki/MediaWiki:Common.css ******/\n/* Since GoldenDict support is not Wikipedia-specific, we don't include all\n * of it, and besides, it's large and volatile anyway. */\n/* It was also edited for the usually narrow article view */\n\n/* Make the list of references smaller */\n.mwiki ol.references {\n  font-size: 100%;\n}\n.mwiki .references-small {\n  font-size: 90%;\n}\n\n.mwiki .references-2column {\n  font-size: 90%;\n  column-count: 2;\n}\n\n/* Highlight clicked reference in blue to help navigation */\n.mwiki ol.references > li:target {\n  background-color: #def;\n}\n\n.mwiki sup.reference:target {\n  background-color: #def;\n}\n\n/* Styling for citations */\n.mwiki cite {\n  font-style: normal;\n  word-wrap: break-word;\n}\n\n/* If there is an inline link to a full citation, the full citation will turn blue when the inline link is clicked */\n.mwiki cite:target {\n  background-color: #def;\n}\n\n/* wikitable/prettytable class for skinning normal tables */\n.mwiki table.wikitable,\n.mwiki table.prettytable {\n  margin: 1em 1em 1em 0;\n  background: #f9f9f9;\n  border: 1px #aaa solid;\n  border-collapse: collapse;\n}\n.mwiki .wikitable th,\n.mwiki .wikitable td,\n.mwiki .prettytable th,\n.mwiki .prettytable td {\n  border: 1px #aaa solid;\n  padding: 0.2em;\n}\n.mwiki .wikitable th,\n.mwiki .prettytable th {\n  background: #f2f2f2;\n  text-align: center;\n}\n.mwiki .wikitable caption,\n.mwiki .prettytable caption {\n  font-weight: bold;\n}\n\n/* default skin for navigation boxes */\n.mwiki table.navbox {\n  /* navbox container style */\n  border: 1px solid #aaa;\n  width: 100%;\n  margin: auto;\n  clear: both;\n  font-size: 88%;\n  text-align: center;\n  padding: 1px;\n}\n.mwiki table.navbox + table.navbox {\n  margin-top: -1px; /* single pixel border between adjacent navboxes (doesn't work for IE6, but that's okay) */\n}\n.mwiki .navbox-title,\n.mwiki .navbox-abovebelow,\n.mwiki table.navbox th {\n  text-align: center; /* title and above/below styles */\n  padding-left: 1em;\n  padding-right: 1em;\n}\n.mwiki .navbox-group {\n  /* group style */\n  white-space: nowrap;\n  text-align: right;\n  font-weight: bold;\n  padding-left: 1em;\n  padding-right: 1em;\n}\n.mwiki .navbox,\n.mwiki .navbox-subgroup {\n  background: #fdfdfd; /* Background color */\n}\n.mwiki .navbox-list {\n  border-color: #fdfdfd; /* Must match background color */\n}\n.mwiki .navbox-title,\n.mwiki table.navbox th {\n  background: #ccccff; /* Level 1 color */\n}\n.mwiki .navbox-abovebelow,\n.mwiki .navbox-group,\n.mwiki .navbox-subgroup .navbox-title {\n  background: #ddddff; /* Level 2 color */\n}\n.mwiki .navbox-subgroup .navbox-group,\n.mwiki .navbox-subgroup .navbox-abovebelow {\n  background: #e6e6ff; /* Level 3 color */\n}\n.mwiki .navbox-even {\n  background: #f7f7f7; /* Even row striping */\n}\n.mwiki .navbox-odd {\n  background: transparent; /* Odd row striping */\n}\n\n.mwiki .collapseButton {\n  /* 'show'/'hide' buttons created dynamically by the        */\n  float: right; /* CollapsibleTables javascript in [[MediaWiki:Common.js]] */\n  font-weight: normal; /* are styled here so they can be customised.              */\n  text-align: right;\n  width: auto;\n}\n.mwiki .navbox .collapseButton {\n  /* In navboxes, the show/hide button balances the vde links from */\n  width: 6em; /* [[Template:Tnavbar]], so they need to be the same width.      */\n}\n\n/* Infobox template style */\n.mwiki .infobox {\n  border: 1px solid #aaa;\n  background-color: #f9f9f9;\n  color: black;\n  /*    margin: 0.5em 0 0.5em 1em;*/\n  margin: 10px auto 0;\n  padding: 0.2em;\n  /*\n    float: right;\n    clear: right;*/\n}\n\n.mwiki .infobox td,\n.mwiki .infobox th {\n  vertical-align: top;\n}\n.mwiki .infobox caption {\n  font-size: larger;\n}\n.mwiki .infobox.bordered {\n  border-collapse: collapse;\n}\n.mwiki .infobox.bordered td,\n.mwiki .infobox.bordered th {\n  border: 1px solid #aaa;\n}\n.mwiki .infobox.bordered .borderless td,\n.mwiki .infobox.bordered .borderless th {\n  border: 0;\n}\n\n.mwiki .infobox.sisterproject {\n  width: 20em;\n  font-size: 90%;\n}\n\n.mwiki .infobox.standard-talk {\n  border: 1px solid #c0c090;\n  background-color: #f8eaba;\n}\n.mwiki .infobox.standard-talk.bordered td,\n.mwiki .infobox.standard-talk.bordered th {\n  border: 1px solid #c0c090;\n}\n\n/* styles for bordered infobox with merged rows */\n.mwiki .infobox.bordered .mergedtoprow td,\n.mwiki .infobox.bordered .mergedtoprow th {\n  border: 0;\n  border-top: 1px solid #aaa;\n  border-right: 1px solid #aaa;\n}\n\n.mwiki .infobox.bordered .mergedrow td,\n.mwiki .infobox.bordered .mergedrow th {\n  border: 0;\n  border-right: 1px solid #aaa;\n}\n\n/* Styles for geography infoboxes, e.g. countries, country subdivisions, cities, etc. */\n.mwiki .infobox.geography {\n  text-align: left;\n  border-collapse: collapse;\n  line-height: 1.2em;\n  font-size: 90%;\n}\n\n.mwiki .infobox.geography td,\n.mwiki .infobox.geography th {\n  border-top: solid 1px #aaa;\n  padding: 0.4em 0.6em 0.4em 0.6em;\n}\n.mwiki .infobox.geography .mergedtoprow td,\n.mwiki .infobox.geography .mergedtoprow th {\n  border-top: solid 1px #aaa;\n  padding: 0.4em 0.6em 0.2em 0.6em;\n}\n\n.mwiki .infobox.geography .mergedrow td,\n.mwiki .infobox.geography .mergedrow th {\n  border: 0;\n  padding: 0 0.6em 0.2em 0.6em;\n}\n\n.mwiki .infobox.geography .mergedbottomrow td,\n.mwiki .infobox.geography .mergedbottomrow th {\n  border-top: 0;\n  border-bottom: solid 1px #aaa;\n  padding: 0 0.6em 0.4em 0.6em;\n}\n\n.mwiki .infobox.geography .maptable td,\n.mwiki .infobox.geography .maptable th {\n  border: 0;\n  padding: 0;\n}\n\n/* Style for \"notices\" */\n.mwiki .notice {\n  margin: 1em;\n  padding: 0.2em;\n}\n\n.mwiki #disambig {\n  border-top: 1px solid #ccc;\n  border-bottom: 1px solid #ccc;\n}\n\n.mwiki .rellink,\n.mwiki .dablink {\n  font-style: italic;\n  padding-left: 2em;\n}\n.mwiki .rellink i,\n.mwiki .dablink i {\n  font-style: normal;\n}\n\n/* Article message box styles */\n.mwiki table.ambox {\n  /* 10% = Will not overlap with other elements */\n  margin: -1px 10% 0px; /* -1px = Single border between stacked boxes in all browsers */\n  border: 1px solid #aaa;\n  border-left: 10px solid #1e90ff; /* Default \"notice\" blue */\n  background: #fbfbfb;\n}\n.mwiki .ambox th.mbox-text,\n.mwiki .ambox td.mbox-text {\n  /* The message body cell(s) */\n  padding: 0.25em 0.5em; /* 0.5em left/right */\n}\n.mwiki .ambox td.mbox-image {\n  /* The left image cell */\n  padding: 2px 0 2px 0.5em; /* 0.5em left, 0px right */\n}\n.mwiki .ambox td.mbox-imageright {\n  /* The right image cell */\n  padding: 2px 0.5em 2px 0; /* 0px left, 0.5em right */\n}\n\n/* Standard Navigationsleisten, aka box hiding thingy from .de.  Documentation at [[Wikipedia:NavFrame]]. */\n.mwiki div.NavFrame {\n  margin: 0;\n  padding: 4px;\n  border: 1px solid #aaa;\n  text-align: center;\n  border-collapse: collapse;\n  font-size: 95%;\n}\n.mwiki div.NavFrame + div.NavFrame {\n  border-top-style: none;\n  border-top-style: hidden;\n}\n.mwiki div.NavPic {\n  background-color: #fff;\n  margin: 0;\n  padding: 2px;\n  float: left;\n}\n.mwiki div.NavFrame div.NavHead {\n  height: 1.6em;\n  font-weight: bold;\n  background-color: #ccf;\n  position: relative;\n}\n.mwiki div.NavFrame p {\n  font-size: 100%;\n}\n.mwiki div.NavFrame div.NavContent {\n  font-size: 100%;\n}\n.mwiki div.NavFrame div.NavContent p {\n  font-size: 100%;\n}\n.mwiki div.NavEnd {\n  margin: 0;\n  padding: 0;\n  line-height: 1px;\n  clear: both;\n}\n.mwiki a.NavToggle {\n  position: absolute;\n  top: 0;\n  right: 3px;\n  font-weight: normal;\n  font-size: 90%;\n}\n\n/****** Wiktionary-specific excerpts *********/\n\n.mwiki .audiolink a {\n  background: url(\"qrc:///icons/audio.png\") center left no-repeat !important;\n  padding-left: 20px !important;\n  padding-right: 0 !important;\n}\n\n/* default setting for [[:Category:Inflection templates]] */\n\n.mwiki .infl-inline {\n  display: inline;\n}\n.mwiki .infl-table {\n  display: none;\n}\n/****default hide dict icon ***/\n.gddicticon {\n  display: none;\n}\n\n.gdexpandicon {\n  cursor: pointer;\n  width: 16px;\n  height: 16px;\n  vertical-align: text-bottom;\n  content: url(\"qrc:///icons/old-arrow.svg\");\n}\n\n.gdcollapseicon {\n  cursor: pointer;\n  width: 16px;\n  height: 16px;\n  vertical-align: text-bottom;\n  content: url(\"qrc:///icons/old-downarrow.svg\");\n}\n\n/********** Slob dictionaries ***********/\n\n.slobdict img.imgtex {\n  vertical-align: baseline !important;\n}\n\n/************* GLS dictionaries **************/\n\n.glsdict_headwords {\n  font-weight: bold;\n  margin-top: 15px;\n  margin-bottom: 10px;\n  font-size: 116%;\n}\n\n.gls_wav img {\n  vertical-align: middle;\n}\n","article-style-st-lingoes-blue.css":"body {\n  background: #eaf0f8;\n  margin: 0.3em;\n  font-family:\n    \"Arial Unicode MS\", \"Lucida Sans Unicode\", Tahoma, Verdana,\n    \"Palatino Linotype\", sans-serif;\n  line-height: 120%;\n}\n\na {\n  text-decoration: none;\n  color: #18a3fa;\n}\n\na:hover {\n  text-decoration: underline;\n}\n\n.gdarticle {\n  background: #fffef2;\n  margin-top: 0.1em;\n  margin-bottom: 0.35em;\n  padding: 5px;\n  padding-top: -10px;\n  border: 1px solid #c7d4dc;\n  border-radius: 8px;\n}\n\n.gdactivearticle {\n  background: #fffef2;\n  border: 1px solid #92b0dd;\n}\n\n.gdarticleseparator + script + .gdactivearticle .gddictname {\n  border-top: 1px solid #92b0dd;\n  border-right: 1px solid #92b0dd;\n}\n\n.gddictname {\n  display: flex;\n  justify-content: flex-end;\n  font-size: 12px;\n  font-weight: normal;\n  border: 0px;\n  border-top: 1px solid #c7d4dc;\n  border-right: 1px solid #c7d4dc;\n  border-top-right-radius: 8px;\n  border-bottom-left-radius: 6px;\n  margin: -6px;\n  margin-bottom: 5px;\n  margin-left: 2px;\n  padding-right: 0.4em;\n  color: #34517d;\n  background: #dde6f5;\n  user-select: none;\n  cursor: default;\n}\n\n/* Actual text with the dictionary title */\n.gddicttitle {\n  display: block;\n  order: 1;\n}\n\n.gdactivearticle .gddictname {\n  border-top: 1px solid #92b0dd;\n  border-right: 1px solid #92b0dd;\n  color: darkblue;\n  background: #cfddf0;\n}\n\n.gdcollapsedarticle .gddictname {\n  opacity: 0.7;\n}\n\n/* Nice diagonal pattern for the collapsed article */\n.gdcollapsedarticle {\n  background-image: linear-gradient(\n    to bottom right,\n    #ccc 0%,\n    #ccc 25%,\n    #bbb 25%,\n    #bbb 50%,\n    #ccc 50%,\n    #ccc 75%,\n    #bbb 75%\n  );\n  background-size: 50px 50px;\n}\n\n/* Move the collapse/expand buttons to the last, 3rd position */\n.collapse_expand_area {\n  display: block;\n  order: 3;\n}\n\n.gddicticon {\n  display: block;\n  vertical-align: text-bottom;\n  padding-right: -1em;\n  padding-left: 0.3em;\n  order: 2;\n}\n\n.gdexpandicon,\n.gdexpandicon:hover,\n.gdcollapseicon,\n.gdcollapseicon:hover {\n  width: auto;\n  height: 100%;\n  vertical-align: text-bottom;\n}\n\n.gdexpandicon {\n  content: url(\"qrc:///icons/expand_article.svg\");\n}\n\n.gdexpandicon:hover {\n  content: url(\"qrc:///icons/expand_article_hovered.svg\");\n}\n\n.gdcollapseicon {\n  content: url(\"qrc:///icons/collapse_article.svg\");\n}\n\n.gdcollapseicon:hover {\n  content: url(\"qrc:///icons/collapse_article_hovered.svg\");\n}\n\n.gdarticleseparator {\n  display: none;\n  clear: both;\n}\n\n/* The 'From ' string which preceeds dictionary name in the heading */\n.gdfromprefix {\n  display: none;\n}\n\n/* Headers */\nh3 {\n  color: inherit;\n  font-family: Arial, sans-serif;\n}\n\n/* The first headword in a (possibly) multi-headword DSL article */\n.gdarticlebody > div:first-child .dsl_headwords {\n  margin-top: -3px;\n  display: inline-block;\n}\n\n.mwiki .toc,\n.mwiki .metadata,\n.mwiki .mbox-small,\n.mwiki .plainlinks {\n  display: none;\n}\n\n.gddicticon img {\n  border: 0;\n  height: 15px;\n  vertical-align: text-top;\n}\n\n/* Text selection */\n::selection {\n  background: #839ec7;\n  color: #fff;\n}\n\ncode::selection {\n  background: #839ec7;\n}\n\n/******** DSL Dictionaries ****************/\n\n/* DSL headwords */\n.dsl_headwords {\n  color: inherit;\n  font-family: Arial, sans-serif;\n}\n\n/* Formatting */\n.dsl_b {\n  font-family: Arial, sans-serif;\n}\n\n.dsl_ex,\n.dsl_ex .dsl_opt {\n  color: slategray;\n}\n\n.dsl_ref {\n  color: #0000dd;\n}\n\n.dsl_url {\n  color: #0000dd;\n}\n\n/* Stress settings */\n.dsl_stress_without_accent,\n.dsl_opt .dsl_ex .dsl_stress_without_accent {\n  display: none;\n  color: green;\n}\n\n.dsl_stress_with_accent,\n.dsl_opt .dsl_ex .dsl_stress_with_accent {\n  display: inline;\n  color: #dd0000;\n}\n.dsl_stress,\n.dsl_opt .dsl_ex .dsl_stress {\n  display: inline;\n  color: blue;\n}\n\n/* Sound icon */\n.dsl_s_wav img {\n  display: none;\n}\n\n.dsl_s_wav a {\n  text-decoration: none;\n  user-select: none;\n  display: inline-block;\n  width: 18px;\n  height: 18px;\n  border-radius: 100px;\n  text-align: center;\n  vertical-align: text-bottom;\n  color: #1a3300;\n  border: 1px solid #798415;\n  box-shadow:\n    1px 1px #ccc,\n    inset -1px -1px #4e7500;\n\n  background: linear-gradient(\n    to bottom right,\n    rgba(191, 210, 85, 1) 0%,\n    rgba(142, 185, 42, 1) 50%,\n    rgba(114, 170, 0, 1) 51%,\n    rgba(158, 203, 45, 1) 100%\n  );\n}\n\n.dsl_s_wav a:hover {\n  background: linear-gradient(\n    to bottom right,\n    #e6f0a3 0%,\n    #d2e638 50%,\n    #c3d825 51%,\n    #dbf043 100%\n  );\n\n  border: 1px solid #a2b01c;\n  box-shadow:\n    1px 1px #ccc,\n    inset -1px -1px #8a991a;\n}\n\n.dsl_s_wav a:active {\n  box-shadow:\n    1px 1px #ccc,\n    inset 1px 1px #b1c421;\n}\n\n.dsl_s_wav a:after {\n  display: inline-block;\n  font-family: \"Webdings\", sans-serif;\n  content: \"X\";\n  width: 18px;\n  height: 18px;\n  font-size: 16px;\n  text-align: center;\n  vertical-align: center;\n  background-clip: text;\n  color: #e6ef8f;\n  -webkit-text-stroke: 1px #51580e;\n}\n\n.dsl_s_wav a:hover:after {\n  -webkit-text-stroke: 1px #656e11;\n}\n\n/******** Verbix Dictionaries ****************/\n\n.sdct_h .normal {\n  font-family: Arial, sans-serif;\n  font-size: 10pt;\n  color: #000000;\n  font-weight: normal;\n  text-decoration: none;\n}\n\n.sdct_h .irregular {\n  font-family: Arial, sans-serif;\n  font-size: 10pt;\n  color: #ff0000;\n  font-weight: bold;\n  text-decoration: none;\n}\n\n.sdct_h .orto {\n  font-family: Arial, sans-serif;\n  font-size: 10pt;\n  color: #0000ff;\n  font-weight: normal;\n  text-decoration: none;\n}\n\n.sdct_h .archaic {\n  font-family: Arial, sans-serif;\n  font-size: 10pt;\n  color: #800080;\n  font-weight: normal;\n  text-decoration: none;\n}\n\n.sdct_h .notused {\n  font-family: Arial, sans-serif;\n  font-size: 10pt;\n  color: #808080;\n  font-weight: normal;\n  text-decoration: none;\n}\n\n.sdct_h .pronoun {\n  font-family: Arial, sans-serif;\n  font-size: 10pt;\n  color: #008000;\n  font-weight: normal;\n  text-decoration: none;\n}\n\n.sdct_h > table {\n  border: 1px solid #444444;\n  border-collapse: collapse;\n}\n\n.sdct_h td.verbtable {\n  border: 1px solid #444444;\n}\n\n.sdct_h th {\n  background-color: #a6c9ef;\n  font-weight: bold;\n}\n\n.sdct_h .mini {\n  font-size: 8pt;\n  font-weight: normal;\n  color: #808080;\n}\n\n.sdct_h div.spacerline {\n  clear: both;\n  margin-left: 8px;\n  width: 100%;\n  border-top: 1px solid #ccc;\n}\n\n.sdct_h div.spacer {\n  clear: both;\n}\n\n.sdct_h div.float {\n  margin-left: 8px;\n  float: left;\n}\n\n.sdct_h div.float400 {\n  margin-left: 8px;\n  float: left;\n  width: 400px;\n}\n\n.sdct_h div.float250color {\n  margin-left: 8px;\n  float: left;\n  width: 250px;\n  border-style: dashed;\n  border-color: #0033cc;\n  border-collapse: collapse;\n  border-width: 1px;\n  background-color: #eeeeee;\n  padding: 8px 8px 8px 8px;\n}\n","article-style-st-lingoes.css":"a {\n  color: #2233bb;\n  text-decoration: none;\n}\n\na:hover {\n  color: #6677ff;\n}\n\n::selection {\n  background: #3399ff;\n  color: white;\n}\n\nbody {\n  background: #fffef2;\n  color: black;\n  font-family: Tahoma, Verdana, SimSun, SimSun-ExtB, sans-serif;\n  margin: 5px;\n}\n\n.gdarticle {\n  background: #fffef2;\n  margin-top: -8px;\n  position: relative;\n}\n\n.gddicticon {\n  display: inline;\n  margin-left: -3px;\n  padding-right: 5px;\n}\n\n.gddicticon img {\n  border: 0px;\n  height: 16px;\n  vertical-align: text-top;\n}\n\n.gdexpandicon,\n.gdexpandicon:hover,\n.gdcollapseicon,\n.gdcollapseicon:hover {\n  width: auto;\n  height: 100%;\n  vertical-align: text-bottom;\n}\n\n.gdexpandicon {\n  content: url(\"qrc:///icons/expand_article.svg\");\n}\n\n.gdexpandicon:hover {\n  content: url(\"qrc:///icons/expand_article_hovered.svg\");\n}\n\n.gdcollapseicon {\n  content: url(\"qrc:///icons/collapse_article.svg\");\n}\n\n.gdcollapseicon:hover {\n  content: url(\"qrc:///icons/collapse_article_hovered.svg\");\n}\n\n.gdfromprefix {\n  display: none;\n}\n\n.gddictname {\n  display: flex;\n  align-items: center;\n  width: 100%;\n  box-sizing: border-box;\n  padding: 0.5em 0.5em;\n  margin-top: 1em;\n  margin-bottom: 0;\n  background: #cfddf0;\n  color: #000080;\n  font-weight: normal;\n  font-size: 12px;\n  cursor: pointer;\n  user-select: none;\n}\n\n.collapse_expand_area {\n  position: absolute;\n  right: 0px;\n}\n\n.gdarticlebody {\n  clear: both;\n  border-top: 1px solid #92b0dd;\n  margin-top: 1em;\n}\n","article-style-st-lingvo.css":"html {\n  background-color: white;\n}\n\nbody {\n  background: white;\n}\n\na:hover {\n  text-decoration: underline;\n}\n\n.gdarticle {\n  background: white;\n}\n\n/* The 'From ' string which preceeds dictionary name in the heading */\n.gdfromprefix {\n  display: none;\n}\n\n/* Dictionary's name heading */\n.gddictname {\n  padding: 0.2em;\n  padding-left: 0.5em;\n  margin-bottom: 0.1em;\n  font-size: 14px;\n  font-weight: normal;\n  float: right;\n  border: 1px solid white;\n  margin-top: 7px;\n  color: #7f7f7f;\n  background: white;\n}\n\n.gdarticleseparator + script + .gdarticle .gddictname {\n  border-top: 1px solid #ccc;\n  /*  margin-top: 11px;*/\n}\n\n.gdactivearticle .gddictname {\n  font-weight: normal;\n\n  float: right;\n  border: 1px solid #b3d7f7;\n  margin-top: 7px;\n  color: #0066ff;\n  background: #deecf8;\n}\n\n.gdarticleseparator + script + .gdactivearticle .gddictname {\n  border-top: 1px solid #b3d7f7;\n  /*  margin-top: 11px;*/\n}\n\n.gdarticleseparator {\n  margin-top: 10px;\n  border-bottom: 1px solid #cccccc;\n  margin-bottom: 0px;\n  width: 100%;\n  display: inline-block;\n  clear: both;\n}\n\n.gddictname + h3,\n.gddictname + .dsl_article > .dsl_headwords {\n  margin-top: 10px;\n}\n\n.dsl_ex,\n.dsl_ex .dsl_opt {\n  color: inherit;\n}\n\n.dsl_com {\n  color: black;\n}\n","article-style-st-modern.css":"html {\n  background-color: white;\n}\n\nbody {\n  margin: 0;\n  background: white;\n}\n\na {\n  text-decoration: none;\n  color: #18a3fa;\n}\n\na:hover {\n  text-decoration: underline;\n}\n\n.gdarticle {\n  margin-top: 0.1em;\n  margin-bottom: 0.4em;\n  padding: 5px;\n  border: 1px solid #d0dde2;\n  border-radius: 8px;\n  background: white;\n  padding-left: 2em;\n  padding-right: 2em;\n}\n\n.gdactivearticle {\n  border: 1px solid #3399ff;\n}\n\n.gdarticleseparator + script + .gdactivearticle .gddictname {\n  border-top: 1px solid #3399ff;\n}\n\n.gdarticleseparator {\n  display: none;\n  clear: both;\n}\n\n/* Hide the 'From ' string which precedes dictionary name in the heading */\n.gdfromprefix {\n  display: none;\n}\n\n.gddictname {\n  display: flex;\n  justify-content: flex-end;\n  font-size: 12px;\n  font-weight: normal;\n  border: 0;\n  border-bottom-right-radius: 8px;\n  border-bottom-left-radius: 8px;\n  margin: -6px;\n  margin-bottom: 5px;\n  margin-left: 2px;\n  padding-right: 0.3em;\n  color: #4480f8;\n  background: #e0e8f0;\n  user-select: none;\n  cursor: default;\n}\n\n/* Actual text with the dictionary title */\n.gddicttitle {\n  display: block;\n  order: 1;\n}\n\n.gdactivearticle .gddictname {\n  font-weight: normal;\n  margin: -6px;\n  margin-bottom: 5px;\n  margin-left: 2px;\n  border: 1px solid #3399ff;\n  color: #0066cc;\n  background: #deecf8;\n}\n\n.gdcollapsedarticle .gddictname {\n  opacity: 0.7;\n}\n\n/* Nice diagonal pattern for the collapsed article */\n.gdcollapsedarticle {\n  background-image: linear-gradient(\n    to bottom right,\n    #ccc 0%,\n    #ccc 25%,\n    #bbb 25%,\n    #bbb 50%,\n    #ccc 50%,\n    #ccc 75%,\n    #bbb 75%\n  );\n  background-size: 50px 50px;\n}\n\n/* Move the collapse/expand buttons to the last, 3rd position */\n.collapse_expand_area {\n  display: block;\n  order: 3;\n}\n\n.gddicticon {\n  display: block;\n  vertical-align: text-bottom;\n  padding-right: -1em;\n  padding-left: 0.3em;\n  order: 2;\n}\n\n.gddicticon img {\n  height: 1.3em;\n}\n\n.gdexpandicon,\n.gdexpandicon:hover,\n.gdcollapseicon,\n.gdcollapseicon:hover {\n  width: auto;\n  height: 100%;\n  vertical-align: text-bottom;\n}\n\n.gdexpandicon {\n  content: url(\"qrc:///icons/expand_article.svg\");\n}\n\n.gdexpandicon:hover {\n  content: url(\"qrc:///icons/expand_article_hovered.svg\");\n}\n\n.gdcollapseicon {\n  content: url(\"qrc:///icons/collapse_article.svg\");\n}\n\n.gdcollapseicon:hover {\n  content: url(\"qrc:///icons/collapse_article_hovered.svg\");\n}\n\n.gdarticlebody {\n  position: relative;\n}\n\n/* The first headword in a (possibly) multi-headword DSL article */\n.gdarticlebody > div:first-child .dsl_headwords {\n  margin-top: -3px;\n  display: inline-block;\n}\n\n.gdspellsuggestion {\n  /* Add some vertical space before the article */\n  margin-top: 1.5em;\n}\n\n.dsl_ex,\n.dsl_ex .dsl_opt {\n  color: steelblue;\n}\n\n::selection {\n  background: #cc0000;\n  color: #fff;\n}\n\ncode::selection {\n  background: #333333;\n}\n"};
